export const KENNISBANK_DEEL1 = [
  {"v": "Waarom wordt een lekdetectierapport soms niet direct gedeeld met de verzekeraar?", "a": "Een lekdetectierapport wordt soms bewust niet direct aangeleverd om het risico op afwijzing van de claim te beperken, bijvoorbeeld wanneer er een risico bestaat dat de schade wordt toegeschreven aan achterstallig onderhoud."},
  {"v": "Is het afsluiten van een rechtsbijstandverzekering een vast agendapunt tijdens de vergaderingen?", "a": "Het afsluiten van een rechtsbijstandverzekering wordt voortaan standaard meegenomen in de agenda's van de vergaderingen."},
  {"v": "Wie is verantwoordelijk voor het verhelpen van schimmel door condens en gebrekkige ventilatie?", "a": "Wanneer schimmelvorming wordt veroorzaakt door bewonersgedrag of een gebrek aan ventilatiemogelijkheden (zoals het ontbreken van roosters in kozijnen of onvoldoende stoken), is dit geen gebrek dat door de Vereniging van Eigenaren (VvE) wordt verholpen. De eigenaar dient dit zelf te verhelpen door de ventilatie te verbeteren en de ruimtes correct te verwarmen."},
  {"v": "Wat moet ik doen bij dringende rioleringsproblemen nadat er een melding is gemaakt?", "a": "Wanneer er een melding is gemaakt bij de rioolservice en de situatie lijkt dringend, kunt u zelf contact opnemen met het gespecialiseerde bedrijf voor een afspraak onder verwijzing naar de eerdere melding vanuit de VvE beheerder."},
  {"v": "Is informatie over de VvE, zoals schadeafwikkelingen en offertes, opvraagbaar voor leden?", "a": "Documenten en zaken met betrekking tot de VvE zijn beschikbaar en opvraagbaar voor de leden."},
  {"v": "Welke stappen moeten worden ondernomen bij funderingsproblemen zoals wateroverlast in de kelder, schimmel of zwam?", "a": "Wanneer er problemen zijn met de fundering zoals zwam, schimmel of wateroverlast, kan er een gespecialiseerd bedrijf worden ingeschakeld voor een inspectie of om de fundering te dichten. Indien de algemene ledenvergadering (ALV) zelf suggesties heeft voor een specifiek bedrijf, kan dit uiteraard ook worden overwogen."},
  {"v": "Hoe zijn de kosten voor glasverzekeringen binnen de VvE geregeld?", "a": "Wanneer in het reglement bij de kosten inzake de afgesloten verzekeringen door de vergadering ook het glas (woning) is opgenomen, vallen deze kosten binnen de vereniging. Eventuele wijzigingen in de verzekeringsportefeuille kunnen tijdens de Algemene Ledenvergadering (ALV) worden besproken."},
  {"v": "Wat gebeurt er als er na de afronding van een project geld overblijft van een extra bijdrage?", "a": "Mocht er na afronding een stuk overblijven, kan de vergadering besluiten een deel terug te storten naar de leden. Het is echter vaak verstandiger dit in reserve te houden voor toekomstig onderhoud."},
  {"v": "Hoe gaat de verzekeraar om met een verzoek tot contra-expertise bij een schademelding?", "a": "Wanneer er onenigheid ontstaat over de schadevaststelling door de expert van de verzekeraar, kan er een verzoek tot contra-expertise worden ingediend. De verzekeraar beoordeelt dit verzoek conform de polisvoorwaarden en de geldende procedures voor schadeafhandeling."},
  {"v": "Wat is de wettelijke termijn voor de uitnodiging van een Algemene Ledenvergadering?", "a": "Dat verschilt per splitsingsakte en modelreglement. Wij hanteren vaak een uitnodigingstermijn van 15 dagen plus 2 dagen."},
  {"v": "Wat zijn de ervaringen van Totaal VvE Beheer met het bedrijf CED voor taxaties, gezien de wisselende online reviews?", "a": "Wij hebben geen klachten over CED. De meeste negatieve reviews lijken betrekking te hebben op schadeafhandeling, wat een andere tak is binnen de organisatie. Met de brandschade-experts binnen dat bedrijf hebben wij juist zeer goed contact."},
  {"v": "Zijn de notulen van het afgelopen jaar al beschikbaar voor de verkoop van mijn appartement?", "a": "In het klantportaal kunt u zien of de notulen beschikbaar zijn."},
  {"v": "Wat moet ik doen als mijn ramen na onderhoudswerkzaamheden niet goed zijn schoongemaakt door het uitvoerende bedrijf?", "a": "Om de situatie te kunnen beoordelen en actie te ondernemen richting het uitvoerende bedrijf, is het noodzakelijk om foto's van de vervuiling aan te leveren ter beoordeling."},
  {"v": "Waar kan ik informatie vinden over de voortgang of details van een wijziging in de splitsingsakte?", "a": "Voor specifieke details over de voortgang of de exacte inhoud van een wijziging in de splitsingsakte kunt u contact opnemen met de behandelend notaris. Totaal VvE Beheer beschikt niet altijd over de complete informatie zolang het proces bij de notaris loopt."},
  {"v": "Kan een schildersbedrijf bij het uitvoeren van schilderwerk aan de kozijnen ook direct het glas vervangen door dubbele beglazing (HR++)?", "a": "Totaal VvE Beheer kan bij de uitvoerende partij nagaan in hoeverre zij, naast het schilderwerk, ook het vervangen van glas naar dubbel glas (HR++) kunnen verzorgen. Indien dit gewenst is, dient specifiek aangegeven te worden voor welke kozijnen dit verzoek geldt, zodat dit met de glaszetters afgestemd kan worden."},
  {"v": "Is het raadzaam om een standleiding direct volledig te vervangen als deze deels openligt voor herstelwerkzaamheden, ook als er nog geen directe problemen zijn?", "a": "Wanneer een standleiding nog openligt, is het kostentechnisch voor de langere termijn vaak een betere optie om deze direct volledig te vervangen. Indien de vergadering hier niet mee akkoord gaat, dient er alsnog een oplossing te komen voor eventuele gevolgschade. Het volledig preventief vervangen van de leiding zorgt ervoor dat verdere schade in de toekomst wordt voorkomen en herstelwerkzaamheden voor alle betrokkenen afgerond kunnen worden."},
  {"v": "Op welk rekeningnummer worden vergoedingen vanuit de vergadering door de beheerder uitbetaald?", "a": "Vergoedingen vanuit de vergadering worden overgemaakt naar het bij de beheerder bekende bankrekeningnummer waarvan ook de maandbijdragen worden betaald."},
  {"v": "Hoe kan er toegang verkregen worden tot het dak voor werkzaamheden aan de rookgasafvoer?", "a": "Voor toegang tot het dak dient er vaak een afspraak gemaakt te worden met de bewoners van de bovenste verdieping, om te bepalen of het dak bereikbaar is via hun balkon of woning."},
  {"v": "Is bij de VvE-beheerder bekend hoe oud de huidige rookgasafvoer van de woning is?", "a": "De VvE-beheerder heeft niet altijd informatie beschikbaar met betrekking tot de ouderdom van de rookgasafvoer. Wanneer er geen informatie bekend is, bestaat het vermoeden dat de leidingen verouderd zijn en dat er bij de installatie van een nieuwe CV-ketel een nieuwe leiding getrokken moet worden naar het dak."},
  {"v": "Is het mogelijk om via WhatsApp of een mobiel nummer filmpjes of mediabestanden te versturen naar de VvE beheerder om schade of gebreken te melden?", "a": "Wij hebben geen mobiele nummers voor het ontvangen van filmpjes of andere mediabestanden. Mocht u deze kunnen e-mailen dan kunnen wij hier naar kijken."},
  {"v": "Waar in de woning kan ik controleren op een lekkende standleiding als ik nog geen schade heb opgemerkt?", "a": "Bij een vermoeden van een lekkende standleiding is het raadzaam om de koof waar de leidingen doorheen lopen te controleren. Indien er sprake is van een lekkage op een andere etage, kan er visueel onderzoek worden gedaan bij de aansluitpunten van de leidingen in uw eigen woning om te zien of daar vocht of schade zichtbaar is."},
  {"v": "Wat zijn de voorwaarden voor het plaatsen van een airco binnen de VvE?", "a": "Voor het plaatsen van een airco gelden specifieke voorwaarden, welke zijn vastgelegd in een officieel document dat op aanvraag beschikbaar is."},
  {"v": "Hoe moet een schade aan het gebouw of glasschade worden gemeld bij een herstel in natura polis?", "a": "Schades aan het gebouw (Rubriek A) kunnen worden gemeld bij de alarmcentrale van uClaim via 088 554 00 05 of via de website www.uclaim.eu. Voor glasschaden (Rubriek C) kunt u contact opnemen met de Glaslijn via 0800 020 50 90. Bij een herstel in natura polis dient de verzekeringsnemer zelf de melding te maken om direct de terugkoppeling te ontvangen."},
  {"v": "Kan ik een juridisch voorstel indienen voor de wijze waarop zaken genotuleerd moeten worden?", "a": "Het staat eigenaren vrij om via een jurist een voorstel te laten doen voor de wijze waarop bepaalde zaken genotuleerd moeten worden. Dit voorstel dient voorafgaand aan de vergadering aangeleverd te worden."},
  {"v": "Mogen eigenaren aanvullende informatie of een toelichting naar de overige leden sturen ter voorbereiding op de ALV?", "a": "Wanneer eigenaren een aanvulling of toelichting willen sturen naar alle leden als voorbereiding op de ALV, kunnen zij dit zelfstandig doen. Het is hierbij gebruikelijk om de VvE-beheerder in de CC van de correspondentie mee te nemen."},
  {"v": "Is het mogelijk om de agenda van de Algemene Ledenvergadering (ALV) nog aan te passen of agendapunten te wijzigen nadat de uitnodiging is verstuurd?", "a": "Wijzigingen aan de agenda worden over het algemeen niet doorgevoerd als de omschrijving te vaag is of als het verzoek tot aanpassing niet gegrond is. De beheerder behoudt zich het recht voor om verzoeken tot afzwakking of wijziging van agendapunten af te wijzen om de duidelijkheid van de vergadering te waarborgen."},
  {"v": "Bij wie kan ik terecht met vragen over de afgrenzing tussen individuele en gemeenschappelijke zaken binnen de VvE?", "a": "Vragen over wat wel en niet individueel is, kunnen worden gesteld aan de beheerder van de VvE. Grote VvE's kunnen specifieke uitzonderingen hebben in de splitsingsakte; deze afwijkingen worden bij Totaal VvE Beheer vermeld onder het kopje kenmerken bij afwijking splitsingsakte."},
  {"v": "Wanneer is het beste moment om de nokvorsten van het dak te laten afsmeren?", "a": "Voor het afsmeren van de nokvorsten is het advies om op warmer weer te wachten in verband met het gebruik van het materiaal voor het afsmeren."},
  {"v": "Wie is verantwoordelijk voor de oplossing en de gevolgschade bij een lekkage van een individuele waterleiding?", "a": "Bij een lekkage van een individuele waterleiding dient de eigenaar van de betreffende leiding, in overleg met de buren die hinder ondervinden, zelf een oplossing te verzorgen. Dit geldt ook voor de afhandeling van de geconstateerde gevolgschade."},
  {"v": "Wat zijn de opties als er onvoldoende saldo op de VvE-rekening staat voor een noodzakelijke opdracht?", "a": "Een optie is dat eigenaren een aanvullende vooruitbetaling doen om het tekort te overbruggen. De onderlinge verhouding en wijze waarop dit gebeurt, kunnen de eigenaren onderling bespreken. Deze vooruitbetaling is opvraagbaar zodra de openstaande vorderingen bij derden zijn voldaan."},
  {"v": "Wie is verantwoordelijk voor de schadeherstel als de schade niet gedekt wordt door de verzekering of een individuele oorzaak heeft?", "a": "Wanneer schade niet bij de verzekering ingediend kan worden of wanneer er sprake is van een individuele schadeoorzaak, dienen de betrokken eigenaren dit onderling met elkaar op te lossen."},
  {"v": "Wie bepaalt welke personen er moeten tekenen voor een volmacht bij de notaris?", "a": "Het is aan de notaris om aan te geven wie er moeten tekenen voor een volmacht."},
  {"v": "Is het mogelijk om als eigenaar een individuele afspraak te maken met de VvE beheerder?", "a": "Wij maken in principe geen afspraken los met individuele eigenaren, met uitzondering van de ledenvergadering. Dit behoort niet tot onze standaard dienstverlening."},
  {"v": "Wie is er verantwoordelijk voor het maken van een afspraak met een loodgieter voor onderzoek naar een lekkage en het verlenen van toegang tot de woningen?", "a": "De betreffende eigenaren zijn zelf verantwoordelijk voor het verzorgen van toegang tot de woningen. Het is niet de taak van de administrateur om te bemiddelen bij het maken van individuele afspraken tussen eigenaren en een externe partij zoals een loodgieter. Indien het niet lukt om gezamenlijk toegang te verlenen voor onderzoek of lekdetectie, is het aan de eigenaren zelf om dit te verhelpen of nader te onderzoeken."},
  {"v": "Wie is er verantwoordelijk voor het onderhoud van het dak onder een dakterras?", "a": "Het dak onder het dakterras valt onder de verantwoordelijkheid van de VvE. Het terras zelf en het bijbehorende hekwerk vallen hier niet onder."},
  {"v": "Hoe is de schoonmaak van het trappenhuis geregeld als er geen collectief schoonmaakcontract is?", "a": "Wanneer er voor een trappenhuis geen schoonmaakcontract is afgesloten, dienen de gebruikers hiervan zelf in onderling overleg voor de schoonmaak zorg te dragen."},
  {"v": "Welke garantie is er dat eigenaren voorgeschoten bedragen voor werkzaamheden uiteindelijk terugkrijgen?", "a": "Voor een voorgeschoten bedrag wordt een vooruitbetaling in de administratie van de VvE opgenomen. Zodra de betaling binnenkomt, kan dit met de betreffende eigenaren worden verrekend."},
  {"v": "Wat gebeurt er als ik voorafgaand aan een vergadering toelichtingen of standpunten indien met betrekking tot agendapunten?", "a": "De standpunten en toelichtingen die u schriftelijk indient met betrekking tot de agendapunten worden als aanvulling op de agendering beschouwd en dienen in de notulen van de vergadering te worden opgenomen."},
  {"v": "Wat moet ik doen als ik nota's ontvang van leveranciers (zoals glazenwassers) die beweren dat er nog bedragen openstaan bij de VvE?", "a": "U kunt deze nota's naar de beheerder doorsturen. Wij zullen de administratie controleren en de openstaande posten bekijken."},
  {"v": "Heeft de VvE recht op een tegemoetkoming vanwege hoge energieprijzen (zoals de TTB) en hoe wordt dit verdeeld?", "a": "Mocht er een tegemoetkoming beschikbaar zijn vanuit de Belastingdienst of overheid voor de VvE, dan zal de VvE deze ontvangen. Indien u hier documentatie over heeft, kunt u deze toesturen zodat wij dit kunnen controleren."},
  {"v": "Wat is het voordeel van een verzekeringspakket met een gratis waardevaststelling?", "a": "Een waardevaststelling biedt garantie tegen onderverzekering, wat essentieel is voor de VvE."},
  {"v": "Waarom moet een defect aan de standleiding eerst worden hersteld voordat gevolgschade aan de opstal wordt aangepakt?", "a": "Experts en herstelpartijen adviseren om eerst de oorzaak (de standleiding) fatsoenlijk aan te pakken voordat zij kunnen starten met het herstel van de gevolgschade."},
  {"v": "Wanneer dient de algemene ledenvergadering (ALV) van de VvE uiterlijk gehouden te worden conform het reglement?", "a": "Dit verschilt per reglement, vraag dit voor de zekerheid na bij uw beheerder."},
  {"v": "Is de VvE verantwoordelijk voor het onderhoud, bijvullen of vernieuwen van individuele cv-ketels?", "a": "Nee, zowel het onderhoud, het bijvullen als het vernieuwen van individuele cv-ketels valt niet binnen de verantwoordelijkheden van de VvE. Omdat de cv-ketels individueel eigendom zijn, worden deze kosten conform de splitsingsakte niet opgenomen in de gezamenlijke begroting en dient de eigenaar dit zelf te regelen."},
  {"v": "Wat is de gebruikelijke gang van zaken bij onderhoud aan mandelige (gemeenschappelijke) zaken tussen twee VvE's?", "a": "Voor mandelige zaken is het gebruikelijk om vooraf afstemming te hebben over de werkzaamheden en de kostenverdeling, in plaats van achteraf een factuur te sturen. Om een verzoek tot kostenverdeling te kunnen beoordelen en voor te leggen aan de leden, is een compleet dossier nodig met een onderbouwing van de werkzaamheden, inclusief de originele offerte en foto's van de situatie voor en na de uitgevoerde werkzaamheden."},
  {"v": "Wat moet er gebeuren als de afwerking rondom nieuw geplaatste kozijnen of het bijbehorende voegwerk niet goed is uitgevoerd?", "a": "Bij het installeren van nieuwe kozijnen is vaak voegherstel rondom nodig. Als de afwerking te wensen overlaat of het voegwerk in de hoeken niet netjes is meegepakt, dient de betreffende aannemer hiervoor aansprakelijk gesteld te worden en terug te komen om de gebreken te herstellen."},
  {"v": "Is het mogelijk om maandelijkse overboekingen die al zijn gedaan te laten staan als vooruitbetaling voor de volgende jaarlijkse factuur?", "a": "Het is geen probleem om maandelijkse betalingen te laten staan. Deze worden dan geregistreerd als vooruitbetalingen die bij de eerstvolgende jaarlijkse factuur zullen worden verrekend."},
  {"v": "Wordt de splitsingsakte volledig vernieuwd bij een wijziging in het reglement?", "a": "De akte wordt niet volledig vernieuwd, maar er wordt een akte van wijziging toegevoegd waarin de uitsluitingen worden gemeld en het laatste standaard reglement van toepassing wordt verklaard."},
  {"v": "Waarvoor kan ik de backoffice omgeving van de VvE beheerder gebruiken?", "a": "In de backoffice omgeving kunt u alle gegevens omtrent uw VvE inzien en direct online een melding maken van benodigd onderhoud of een storing."},
  {"v": "Kan de portiekverlichting aangepast worden naar verlichting met een bewegingssensor om energie te besparen?", "a": "Verzoeken voor het aanpassen van de portiekverlichting, zoals het plaatsen van sensoren, kunnen worden geagendeerd voor de komende Algemene Ledenvergadering (ALV) ter bespreking. Er kan dan tevens worden gekeken of er binnen de VvE bewoners zijn die hier zelf een rol in kunnen betekenen om kosten voor een elektricien te besparen."},
  {"v": "Hoe gaat de VvE beheerder om met vragen van een notaris bij de verkoop van een appartementsrecht of garage?", "a": "Wanneer de notaris zich tot de VvE beheerder richt met specifieke vragen over de verkoop en de VvE (zoals de omvang van het reservefonds), worden deze zo snel mogelijk beantwoord."},
  {"v": "Wat moet ik doen als ik herstelwerkzaamheden aan een lekkage heb laten uitvoeren zonder officiële factuur?", "a": "In het geval dat er geen officiële facturen aanwezig zijn voor herstelwerkzaamheden, is het raadzaam om een overzicht te maken van hoe en wat er precies is opgepakt. Dit overzicht kan vervolgens, samen met eventuele aankoopbonnen van materialen, worden ingebracht tijdens de Algemene Ledenvergadering (ALV) om de kosten middels een vergaderbesluit af te wikkelen."},
  {"v": "Heeft het VvE-beheer informatie over de isolatie van het dak van het gebouw?", "a": "Vraag dit voor de zekerheid na bij uw beheerder."},
  {"v": "Wat is de aanbevolen eerste stap bij het onderzoeken van een lekkage aan een (gedeelde) schoorsteen of het dak?", "a": "In de basis is het laten langskomen van een dakdekker de eerste stap. Een ervaren dakdekker kan vaak direct de oorzaak vaststellen en het probleem binnen het mandaat oppakken. Het inschakelen van een gespecialiseerd onderzoeksbureau is meestal pas nodig als een reguliere inspectie door een vakman niet volstaat."},
  {"v": "Wat is de gebruikelijke betalingstermijn voor facturen?", "a": "De betaling van facturen gebeurt in principe altijd binnen 2 weken."},
  {"v": "Waar moet ik op letten bij het indienen van een schadeclaim met betrekking tot het eigen risico?", "a": "Het is belangrijk om rekening te houden met het eigen risico per gebeurtenis. Het is niet altijd raadzaam om schades die qua bedrag dicht bij het eigen risico liggen in te dienen in verband met registraties in het systeem van verzekeraars (FISH)."},
  {"v": "Zijn de bedragen die in een expertiserapport van de verzekeraar worden genoemd inclusief of exclusief BTW?", "a": "De bedragen in het expertiserapport van de verzekeraar zijn inclusief BTW."},
  {"v": "Wat moet ik doen als er specifieke VvE-informatie of documenten ontbreken in de portaal?", "a": "In het geval er zaken ontbreken, kunt u de betreffende beheerder een e-mail sturen."},
  {"v": "Wat is de procedure voor het melden van zaken zoals schade aan het portiekkozijn of graffiti?", "a": "Na ontvangst van foto's van de schade of de graffiti zullen deze zaken zo spoedig mogelijk worden uitgezet voor herstel."},
  {"v": "Ik ben een nieuwe eigenaar binnen de VvE en zou graag het reglement willen inzien. Kunt u dit naar mij opsturen?", "a": "Het reglement van de VvE kunt u inzien op het klantportaal."},
  {"v": "Welke partijen kunnen worden aanbevolen voor het opstellen of actualiseren van een onderhoudsplan?", "a": "Er zijn diverse gespecialiseerde partijen beschikbaar voor het opstellen van onderhoudsplannen. Totaal VvE Beheer heeft voorkeurspartijen die zij adviseren voor het uitvoeren van deze werkzaamheden."},
  {"v": "Beschikt de beheerder over bouwtekeningen van het pand ten behoeve van een taxatie?", "a": "Vraag dit voor de zekerheid na bij uw beheerder."},
  {"v": "Is het mogelijk om een melding te ontvangen zodra de jaarstukken gereed zijn?", "a": "Zodra de jaarstukken gereed zijn, kunt u deze inzien in het klantportaal. U ontvangt hiervan geen melding."},
  {"v": "Mag een inspectie van een rookgaskanaal in opdracht worden gegeven middels het bestuurdersmandaat?", "a": "Het is mogelijk om een inspectie middels het bestuurdersmandaat in opdracht te geven, mits hierover afstemming heeft plaatsgevonden met de betrokken partijen/beheerder."},
  {"v": "Welke acties moeten er ondernomen worden vanuit de VvE als een CV-ketel op een onbekend rookgaskanaal moet worden aangesloten?", "a": "Wanneer niet duidelijk is hoe een rookgaskanaal loopt, dienen er twee stappen te worden ondernomen: 1. Inspectie: Middels een camerainspectie moet worden vastgesteld tot hoever het kanaal omhoog loopt. 2. Rookgaskanaal verlenging: Op basis van de inspectie kan worden bepaald hoe het bestaande kanaal verlengd kan worden tot aan het dak."},
  {"v": "Kunt u een loodgieter aanbevelen voor het inspecteren van een lekkage?", "a": "Vraag dit voor de zekerheid na bij uw beheerder."},
  {"v": "Wat gebeurt er als de factuur voor herstelwerkzaamheden na een lekkage hoger is dan het door de verzekeraar vastgestelde schadebedrag?", "a": "Een factuur die hoger uitvalt dan het vastgestelde schadebedrag van de verzekeraar is mogelijk. In dat dient de VvE te beslissen of de overige werkzaamheden uitgevoerd mogen worden."},
  {"v": "Welke informatie is er nodig bij het melden van een lekkage?", "a": "Bij het melden van een lekkage is het belangrijk om aan te geven wat de situatie is, ook is het handig om foto's en of video's te delen zodat we de situatie goed kunnen inschatten en de juiste partij kunnen inschakelen."},
  {"v": "Is een garage of opslagruimte gedekt onder de huidige verzekeringspolis van de VvE?", "a": "Dit verschilt per polis, vraag dit voor de zekerheid na bij uw beheerder."},
  {"v": "Waarom wordt een gevel soms niet volledig geïmpregneerd bij renovatiewerkzaamheden?", "a": "In sommige situaties volstaat de huidige staat van de gevel volledig om vochtwerend te zijn. Het selectief of deels impregneren van specifieke etages kan in bepaalde gevallen zelfs leiden tot andere bouwkundige problemen binnen het pand, waardoor het technisch niet raadzaam is om de gehele gevel te behandelen."},
  {"v": "Wat is de procedure bij brandschade als er geen daders bekend zijn?", "a": "Wanneer er sprake is van brandschade en er zijn geen daders bekend, wordt de kwestie afgewikkeld met de verzekering."},
  {"v": "Wat wordt er van de bewoner/huurder verwacht wanneer er dakwerkzaamheden worden uitgevoerd aan het pand?", "a": "Bij dakwerkzaamheden wordt vooraf contact opgenomen met de bewoners van de bovenetage om toegang te verkrijgen indien dit nodig is. Indien er in de offerte wordt aangegeven dat er gewerkt wordt met steigers, zullen deze aan de voorzijde van het pand worden geplaatst."},
  {"v": "Hoe moet waterschade door een daklekkage worden afgehandeld als dit niet onder de verzekering valt?", "a": "Wanneer er sprake is van schade die niet door de verzekering wordt gedekt, dient er een herstelofferte te worden aangeleverd. Deze offerte kan vervolgens ter beoordeling aan de vergadering van eigenaars worden voorgelegd."},
  {"v": "Kan de beheerder informatie verstrekken over de kleurcodes (zoals RAL-codes) van de kozijnen van een specifiek appartement?", "a": "De beheerder heeft hier helaas geen informatie over. Voor specifieke kleurcodes van schilderwerk dient vaak gekeken te worden in de splitsingsakte of bij eerdere onderhoudsverslagen, mits deze beschikbaar zijn gesteld aan het beheer."},
  {"v": "Kan ik als aanstaande eigenaar direct een kopie van het polisblad van de collectieve verzekering opvragen bij de VvE-beheerder?", "a": "De VvE-beheerder mag de huidige polis niet rechtstreeks aan derden verstrekken. Een kopie van het polisblad dient via de huidige eigenaar van het appartementsrecht verzocht te worden."},
  {"v": "Met welke doorlooptijd moet er rekening gehouden worden bij grote planmatige onderhoudswerkzaamheden?", "a": "Het is niet ongebruikelijk dat grotere planmatige klussen meerdere maanden duren voordat de uitvoering kan starten. Hierbij moet tevens rekening worden gehouden met seizoensinvloeden; bepaalde werkzaamheden kunnen bijvoorbeeld tijdens de winterperiode niet worden uitgevoerd vanwege de weersomstandigheden."},
  {"v": "Moet onderhoud aan het dak met spoed uitgevoerd worden als er momenteel geen zware lekkages zijn?", "a": "Hoewel er op een specifiek moment geen sprake hoeft te zijn van zware lekkages, is het altijd de voorkeur om lekkages te voorkomen. Wanneer aannemers bij opname aangeven dat een dak aan vervanging toe is, wordt geadviseerd dit serieus te nemen om toekomstige schade te vermijden."},
  {"v": "Kan de beheerder beslissen om geplande werkzaamheden, zoals dakvervanging, uit te stellen voor de VvE?", "a": "Of werkzaamheden uitgesteld kunnen worden, is aan de VvE (de gezamenlijke eigenaren) en niet aan de beheerder om te bepalen. De beheerder adviseert op basis van offertes en de staat van onderhoud, maar de besluitvorming ligt bij de ledenvergadering."},
  {"v": "Is het mogelijk om een extra brievenbus te laten plaatsen voor een specifiek appartementsrecht?", "a": "Er kan op eigen kosten worden gezorgd voor een extra brievenbus. Hiervoor dienen de specificaties van de gewenste brievenbus te worden doorgegeven aan de beheerder."},
  {"v": "Hoe geef ik een adreswijziging door voor mijn (zakelijke) correspondentie?", "a": "U kunt uw nieuwe adresgegevens schriftelijk of per e-mail aan ons doorgeven. Wij passen de gegevens vervolgens aan in onze administratie voor de betreffende complexen."},
  {"v": "Waarom kan er vertraging optreden bij de uitvoering van planmatig onderhoud nadat de opdracht al is verstrekt?", "a": "Planmatig onderhoud kan in de huidige markt langer duren door een beperkt aanbod van aannemers en personeel. Het verstrekken van een opdracht betekent helaas niet automatisch dat de werkzaamheden nog in hetzelfde kalenderjaar worden opgepakt; de planning is afhankelijk van de beschikbaarheid van de uitvoerende partijen."},
  {"v": "Is het mogelijk om een doorlopende volmacht te verstrekken voor standaardzaken?", "a": "Wij bieden de mogelijkheid om een doorlopende volmacht te ontvangen voor standaardzaken. Voorbeelden van de situaties waarin dit van toepassing is, zijn op aanvraag beschikbaar."},
  {"v": "Hoe worden VvE-leden geïnformeerd over de datum van een taxatie door een externe partij?", "a": "Zodra de communicatie vanuit de externe partij over de datum van de taxatie is ontvangen, wordt dit aan de betrokkenen laten weten."},
  {"v": "Is er een appartementenclausule van toepassing op de collectieve opstalverzekering en is er een aansprakelijkheidsverzekering afgesloten?", "a": "Ja, een appartementenclausule is van toepassing op de collectieve opstalverzekering. Daarnaast heeft de VvE ook een aansprakelijkheidsverzekering afgesloten."},
  {"v": "Bij wie kan ik terecht voor een camera-inspectie van een schoorsteenkanaal als mijn reguliere schoorsteenveger dit niet kan uitvoeren?", "a": "Vraag dit na bij de beheerder, zij kunnen u adviseren welke partij geschikt is."},
  {"v": "Kunnen aanvullende werkzaamheden aan het dak vanuit de reserve van de VvE worden betaald?", "a": "Deze offerte leggen wij middels een schriftelijke stemming aan jullie voor en kan vanuit de reserve betaald worden."},
  {"v": "Wat verandert er aan de verzekeringspolis wanneer er een horecagelegenheid in het pand van de VvE komt?", "a": "Bij de aanwezigheid van horecagelegenheden worden de gebruikelijke clausules in de verzekeringspolis opgenomen. Daarnaast kunnen er specifieke preventiemaatregelen gelden die aan de huurder moeten worden doorgegeven. De premie kan in sommige gevallen ongewijzigd blijven, maar dit hangt af van de beoordeling door de verzekeraar."},
  {"v": "Wat is het advies voor de afrekening van nutsvoorzieningen bij een ondersplitsing zonder eigen aansluitingen?", "a": "Het is raadzaam om tussenmeters te realiseren. Wanneer er gewerkt wordt zonder aparte aansluitingen of tussenmeters, ontstaan er vaak discussies over het verbruik en de kostenverdeling, zeker bij stijgende prijzen of verschillend stookgedrag. Om een gezonde splitsing te behouden, is het essentieel dat eigenaren hierover met elkaar in gesprek gaan."},
  {"v": "Hoe werkt de besluitvorming en administratie bij een ondersplitsing met twee stemgerechtigden?", "a": "Bij een ondersplitsing met twee stemmen is voor alle zaken overeenstemming tussen beide partijen nodig voordat de administratie kan worden gevoerd. Zonder akkoord van beide eigenaren kunnen er geen specifieke reserves, bijdragen of incasso's worden vastgesteld of uitgevoerd."},
  {"v": "Kan de VvE rekeningen voor energie en water betalen als er binnen een ondersplitsing geen overeenstemming is over de bijdragen?", "a": "Als er geen bijdragen worden betaald voor de kosten van stroom, gas en water, kan de VvE deze niet voldoen. Hiervoor zullen eerst de bijdragen vastgesteld moeten worden."},
  {"v": "Wat moet ik doen als mijn appartement of specifieke werkzaamheden niet zijn opgenomen in een offerte voor groot onderhoud, zoals houtrotherstel?", "a": "Wanneer er zaken opgepakt moeten worden die niet in de huidige offerte staan, zal daarvoor een aanvullende offerte opgesteld moeten worden. Om dit proces te versnellen is het raadzaam om een overzicht met foto's van de benodigde werkzaamheden aan te leveren, zodat de situatie beoordeeld kan worden."},
  {"v": "Heeft de VvE beheerder vaste aannemers voor onderhoudswerkzaamheden wanneer de eigen voorkeurspartijen van de klant niet beschikbaar zijn?", "a": "Wanneer vaste partijen van de klant niet langer beschikbaar zijn, kan de VvE beheerder zoeken naar geschikte aannemers. Het is echter ook praktisch om te kijken naar alternatieve voorkeurspartijen die de klant zelf kan aandragen voor het uitbrengen van offertes."},
  {"v": "Wat gebeurt er met de individuele maandbijdragen van de eigenaren als de totale bijdrage aan de hoofdsplitsing wijzigt?", "a": "In het geval de maandbijdragen in de hoofdsplitsing wijzigen, ontvangen de eigenaren hier bericht over en worden de nieuwe maandbijdragen conform de huidige verhouding in dezelfde maand van kracht."},
  {"v": "Is het mogelijk om toestemming te vragen aan de VvE voor tijdelijke verhuur voordat de eigenaar er zelf gaat wonen?", "a": "Een verzoek om een verhuurperiode van bijvoorbeeld 6 maanden (voordat de eigenaar er zelf gaat wonen) kan worden ingediend om te laten bespreken tijdens de Algemene Ledenvergadering (ALV). De vergadering kan dan bepalen of zij hier bezwaar tegen hebben."},
  {"v": "Wat houdt een akkoord op een volmacht in met betrekking tot noodzakelijk onderhoud?", "a": "Binnen de volmacht wordt met een akkoord voor offertes ten behoeve van noodzakelijk onderhoud tevens akkoord gegeven op eventuele noodzakelijke eenmalige extra bijdragen die nodig zijn voor de uitvoering van dit onderhoud."},
  {"v": "Is het mogelijk om werkzaamheden door een aannemer op regiebasis (uren en materiaal) te laten uitvoeren in plaats van via een vaste offerte?", "a": "Afhankelijk van wat de aannemer tegenkomt, kunnen werkzaamheden op basis van nacalculatie worden afgerekend, waarbij het aantal uren en het materiaal naar alle redelijkheid worden gefactureerd. Indien er de voorkeur aan wordt gegeven om met vaste offertes te werken, kan de VvE zelf een offerte aanleveren en het traject regelen."},
  {"v": "Door wie moet een Meerjarenonderhoudsplan (MJOP) worden opgesteld?", "a": "Het opstellen van een MJOP dient vanuit de eigenaren geschreven te worden of door een onafhankelijk bouwkundige."},
  {"v": "Waarom moet er een constructeur worden ingeschakeld bij schade of gebreken aan het gebouw?", "a": "Het inschakelen van een constructeur is noodzakelijk om de technische staat en veiligheid van de constructie te beoordelen, zeker wanneer visuele inspectie (zoals foto's) duidt op mogelijke constructieve problemen. Houd er rekening mee dat hier kosten aan verbonden zijn voor zowel het onderzoek als het toegankelijk maken van de betreffende locaties voor de constructeur."},
  {"v": "Hoe kan een besluit worden genomen over onderhoudszaken die niet op de agenda van de ALV staan?", "a": "Voor zaken die niet op de agenda staan, kan eventueel besloten worden om een Technische Commissie aan te stellen met een mandaat om hierover te beslissen."},
  {"v": "Kunnen de kosten voor werkzaamheden aan gemeenschappelijke delen van het gebouw uit de reservefondsen van de VvE worden betaald?", "a": "Het gemeenschappelijke stuk kan vanuit de reserve betaald worden."},
  {"v": "Wat moet ik doen als er water omhoog komt in mijn toilet of douche wanneer de bovenburen gebruikmaken van het sanitair?", "a": "Wanneer er water omhoog komt bij het gebruik van sanitair op hogere etages, is het advies om verder onderzoek te laten doen naar de standleidingen door middel van een cameraonderzoek en een rookgasonderzoek. Neem contact op met de beheerder van de VvE."},
  {"v": "Is het noodzakelijk om een bevestiging te sturen zodra een betaling is verricht?", "a": "Dit is niet nodig, ons systeem zal dit zelf herkennen."},
  {"v": "Is het mogelijk om de voorschotten voor gas en elektra tussentijds aan te passen?", "a": "De voorschotten voor gas en stroom zijn gebaseerd op de beschikbare verbruiksstukken. Hierin kunnen geen aanpassingen worden gedaan tot het eerstvolgende afrekenmoment."},
  {"v": "Wat gebeurt er als een reparatieverzoek buiten het mandaat van de beheerder valt?", "a": "Indien een reparatieverzoek of onderzoek niet binnen het mandaat kan worden uitgevoerd, zal er eerst een offerte volgen."},
  {"v": "Kan ik een kopie van een bankafschrift van de VvE ontvangen voor de verkoop van mijn woning?", "a": "Ja, een kopie van het bankafschrift van de VvE kan op aanvraag worden verstrekt."},
  {"v": "Beschikt de VvE-beheerder over een kopie van de koopakte van mijn appartement?", "a": "Nee, de koopakte hebben wij als VvE-beheerder niet in ons bezit."},
  {"v": "Wat zijn de regels met betrekking tot het gebruik van de gemeenschappelijke toegang en het portiek?", "a": "Het portiek en de gemeenschappelijke toegang tot het portiek dienen vrijgehouden te worden van obstakels."},
  {"v": "Wat moet de VvE doen als er tijdens onderhoudswerkzaamheden ernstige constructieve gebreken worden geconstateerd aan balkons?", "a": "Er wordt geadviseerd om in de tussentijd geen gebruik van het balkon te maken. Er zal middels een schriftelijke stemming aan de leden een verzoek worden voorgelegd voor een aanvullend mandaat voor de inzet van een constructeur om de situatie te beoordelen."},
  {"v": "Is het toegestaan om zonder toestemming van de VvE door de gevel te gaan met bijvoorbeeld een rookgasafvoer (RGA)?", "a": "Het is niet toegestaan om zonder toestemming door de gevel te gaan met bijvoorbeeld een rookgasafvoer (RGA). Indien dit zonder toestemming is gebeurd, dient deze in principe verwijderd te worden."},
  {"v": "Hoe gaat het beheer om met de privacy van contactgegevens van huurders die worden gedeeld voor reparaties of onderhoud?", "a": "De contactgegevens van huurders worden uitsluitend gedeeld met de betreffende aannemers die de werkzaamheden moeten uitvoeren."},
  {"v": "Worden gaten in de gevel die zijn geboord voor het plaatsen van een steiger weer hersteld?", "a": "In geval van geboorde gaten in de gevel voor de steiger, zullen deze uiteraard worden hersteld."},
  {"v": "Is het gebruikelijk dat kopers/nieuwe eigenaren aanwezig zijn bij een Algemene Ledenvergadering (ALV) vóór de officiële overdracht?", "a": "In principe is het niet gebruikelijk dat nieuwe eigenaren voor een overdracht aanwezig zijn bij de vergadering. Hiervoor zou toestemming gevraagd moeten worden aan de huidige eigenaren. De kopers zouden dan uitsluitend als toehoorder aanwezig kunnen zijn, tenzij er een volmacht wordt verstrekt door de huidige eigenaar."},
  {"v": "Waarom wordt er bij onderhoud aan balkons op een hogere verdieping vaak ook naar de balkons op de verdiepingen daaronder gekeken?", "a": "De staat van balkons binnen hetzelfde complex is veelal soortgelijk. Als een balkon op een hogere etage gebreken vertoont, is de kans groot dat dit bij de onderliggende etages ook het geval is (soms in mindere mate, maar vaak is er wel onderhoud nodig)."},
  {"v": "Wordt er bij kleine VvE's standaard een kascontrole uitgevoerd?", "a": "Bij kleine VvE's vindt er meestal geen kascontrole plaats. Op verzoek kunnen jaarstukken uitgebreid worden doorgenomen op de algemene ledenvergadering."},
  {"v": "Welke mogelijkheden zijn er als de huidige verzekerde som van de opstalverzekering aanzienlijk hoger is dan de berekende herbouwwaarde?", "a": "Wanneer de verzekerde som afwijkt van de herbouwwaarde, zijn er verschillende opties: de verzekerde som verlagen naar het huidige berekende bedrag (waarbij het risico op onderverzekering blijft bestaan), de polis ongewijzigd laten, de som verlagen naar een tussenbedrag met een veiligheidsmarge, of het pand officieel laten taxeren door een deskundige instantie om de verzekerde som op basis van die taxatie aan te passen."},
  {"v": "Waarom staat waterschade niet expliciet vermeld op het overzicht van de verzekering?", "a": "De dekking voor waterschade staat in de voorwaarden van de verzekering vermeld."},
  {"v": "Wanneer kan een zelfbewoningsplicht worden opgenomen in de reglementen van de VvE?", "a": "Voor het invoeren van een zelfbewoningsplicht dient eerst de splitsingsakte te worden aangepast en moet er een nieuw concept van het Huishoudelijke Reglement worden opgesteld."},
  {"v": "Wat moet ik doen bij overlast door omwonenden, zoals stankoverlast?", "a": "Wij adviseren om eerst zelf een poging te doen om aan te kloppen en onderling naar de situatie te kijken voordat er een melding wordt gemaakt."},
  {"v": "Met wie moet ik contact opnemen voor het verifiëren van aktes of juridische details bij een notaris: de VvE-beheerder of moet ik dit zelf doen?", "a": "Dat zouden jullie zelf moeten doen, dit valt buiten de werkzaamheden van de administrateur/bestuurder."},
  {"v": "Wanneer pakt de beheerder een aanschrijving of officieel document van een instantie op?", "a": "Pas wanneer documentatie officieel op papier aan de VvE gericht is, kan en zal de beheerder hiermee aan de slag gaan."},
  {"v": "Zijn er kosten verbonden aan het annuleren van een aanvraag, zoals offertekosten?", "a": "Nee, er worden geen kosten in rekening gebracht zolang er nog geen opdracht is verstrekt."},
  {"v": "Met wie kan ik contact opnemen voor juridische zaken zoals splitsingsaktes?", "a": "Wanneer u een externe partij hierin mee wilt nemen, kunt u het algemene e-mailadres aanhouden."},
  {"v": "Kan de VvE actie ondernemen of een bouwkundige keuring afdwingen wanneer een eigenaar technische installaties (zoals ventilatie of CV) onjuist heeft aangesloten, wat leidt tot overlast of gevaarlijke situaties?", "a": "Vanuit de VvE kan er in dergelijke situaties weinig tot niets worden afgedwongen. In het geval van onjuiste aansluitingen of onveilige situaties door buren wordt geadviseerd om bouw- en woningtoezicht van de gemeente in te schakelen om dit te laten controleren en eventueel handhaven."},
  {"v": "Soms kan de VvE bepaalde zaken niet afdwingen bij overlast of gebreken. Wat moet ik dan doen?", "a": "Wanneer de VvE vanuit haar bevoegdheden weinig of niets kan afdwingen, kan het noodzakelijk zijn om zelf Bouw- en woningtoezicht in te schakelen om de situatie te laten beoordelen."},
  {"v": "Zijn de daklijsten van het pand onderdeel van de VvE?", "a": "Daklijsten zijn onderdeel van de VvE."},
  {"v": "Wat is de procedure als ik een plan of wijziging wil voorleggen aan de vergadering?", "a": "Plannen moeten volledig uitgewerkt worden voorgelegd. Het is doorgaans het meest praktisch als dit ter plaatse doorgenomen wordt met de Technische Commissie (TC), voordat er iets richting de vergadering gaat."},
  {"v": "Hoe kunnen bestaande afspraken over het onderhoud van algemene zaken het beste worden verwerkt bij de overstap naar een nieuw splitsingsreglement?", "a": "Bij de overstap naar een nieuw reglement (zoals Modelreglement 2017) kan de notaris worden verzocht om de specifieke wensen en opmerkingen zoveel mogelijk 1-op-1 over te zetten, inclusief de juiste verwijzingen naar de betreffende artikelen in het nieuwe splitsingsreglement."},
  {"v": "Wat moet ik doen als er sprake is van een hardnekkige verstopping of lekkage waarbij toegang tot de woning van de buren noodzakelijk is, maar zij werken niet mee?", "a": "Wanneer werkzaamheden bij de buren uitgevoerd moeten worden en zij geven geen toestemming, is het advies om zo snel mogelijk Bouw- en Woningtoezicht op locatie te laten komen om een oplossing af te dwingen. Indien u een rechtsbijstandverzekering heeft, kunt u deze inschakelen. Heeft u deze niet, dan dient u de buren minimaal aansprakelijk te stellen; voor hulp hierbij kunt u informeren bij een rechtswinkel."},
  {"v": "Onder welke voorwaarden kan een beheerder iemand sturen voor reparatiewerkzaamheden waarbij hakwerk nodig is?", "a": "Er kan pas iemand gestuurd worden voor reparaties zodra er expliciet toestemming is gegeven om open te hakken wat er opengehakt moet worden (bijvoorbeeld bij de buren indien noodzakelijk)."},
  {"v": "Is een erker onderdeel van de gemeenschappelijke ruimte of wordt deze als individueel eigendom beschouwd?", "a": "Dit hangt af van hoe het in de splitsingsakte is beschreven, vraag dit voor de zekerheid bij de beheerder na."},
  {"v": "Wat moet ik doen als ik een gunstigere offerte ontvang voor noodzakelijke werkzaamheden zoals gevel- of schilderwerk?", "a": "In het geval er een gunstigere offerte volgt, kunt u deze aan ons toesturen. Wij zullen deze vervolgens aan de vergadering voorleggen, dit kan schriftelijk of via de Algemene Ledenvergadering (ALV)."},
  {"v": "Hoe kan de herbouwwaarde voor de opstalverzekering van de VvE het beste worden vastgesteld?", "a": "Om de herbouwwaarde van een pand correct vast te stellen, adviseert Totaal VvE Beheer om een officiële herbouwwaardetaxatie te laten uitvoeren."},
  {"v": "Hoe kan ik een extra sleutel voor mijn voordeur aanvragen en waar kan ik deze ophalen?", "a": "Wanneer er voor uw complex een sleutelplan aanwezig is, kunt u na akkoord van de VvE een extra sleutel laten maken bij de aangewezen sleutelspecialist. U dient de sleutel daar zelf op te halen en direct af te rekenen."},
  {"v": "Wanneer kan er een melding worden ingediend bij de opstalverzekering?", "a": "Het indienen van zaken bij de opstalverzekering is pas mogelijk nadat de schadeoorzaak of schadeoorzaken zijn weggenomen. Houd er rekening mee dat het eigen risico per gebeurtenis geldt."},
  {"v": "Wat moet ik aanleveren als ik een melding maak voor onderhoudszaken?", "a": "Voor onderhoudszaken is altijd een offerte en/of foto's nodig om de melding in behandeling te kunnen nemen."},
  {"v": "Kan Totaal VvE Beheer helpen bij het vergelijken van privéverzekeringen met de verzekeringen van de VvE?", "a": "Wij ondersteunen niet bij het vergelijken van de verschillen tussen uw huidige privéverzekeringen en die voor de VvE. Dit is een taak voor uw verzekeringsadviseur; het is met name belangrijk dat deze controleert of de dekking gelijkwaardig is."},
  {"v": "Heeft de beheerder invloed op de planning of uitvoerdata van aannemers bij werkzaamheden?", "a": "De administrateur/bestuurder heeft geen invloed op de planning of uitvoerdata van aannemers. Dit wordt normaliter door de aannemer zelf gecommuniceerd en uitgevoerd."},
  {"v": "Wat moet er gebeuren als er scheuren in de muren van een appartement zichtbaar zijn?", "a": "Bij het constateren van scheuren kan worden beoordeeld of het om werkingsscheuren gaat. Indien het niet acuut is, is het raadzaam om bij een update van het Meerjarenonderhoudsplan (MJOP) een bouwkundige specifiek naar deze scheuren te laten kijken en dit vervolgens te bespreken in de Algemene Ledenvergadering (ALV)."},
  {"v": "Hoe kan ik extra fietsbeugels of fietsnietjes aanvragen bij de gemeente?", "a": "U kunt via de website van de gemeente een aanvraag indienen voor het laten plaatsen van fietsbeugels in de openbare ruimte."},
  {"v": "Zijn rookmelders verplicht in het gebouw?", "a": "Het is wettelijk verplicht om rookmelders te plaatsen."},
  {"v": "Wat moet ik doen als een regenpijp of hemelwaterafvoer (HWA) verstopt zit en dreigt over te lopen?", "a": "Wanneer een hemelwaterafvoer overloopt en potentieel schade kan veroorzaken, kunt u in overleg met de buren proberen de afvoer door te prikken om de ergste druk te verlichten. Ondertussen zal de VvE beheerder een loodgietersbedrijf inschakelen om de verstopping definitief te verhelpen en eventuele defecte delen van de afvoer te vervangen."},
  {"v": "Hoe wordt de minimale inleg voor het onderhoud van de VvE bepaald?", "a": "De bestuurder geeft aan wat er minimaal ingelegd moet worden voor de uitvoer van het onderhoud. Het is vervolgens aan de ledenvergadering om hier wel of niet mee akkoord te gaan."},
  {"v": "Bij welke instantie kan ik een melding maken van een onveilig of illegaal bouwwerk bij de gemeente?", "a": "U kunt hiervoor een melding maken bij de Haagse Pandbrigade van de gemeente. Het is daarbij belangrijk dat zij weten om welke VvE het gaat en namens welk appartement de melding wordt gedaan."},
  {"v": "Valt het uitvoeren van onderhoud aan de riolering onder de verzekering?", "a": "Het uitvoeren van onderhoud aan de riolering is nooit verzekeringswerk. Werkzaamheden die betrekking hebben op onderhoud hebben niets met de opstalverzekering van doen."},
  {"v": "Is het mogelijk om telefonisch contact op te nemen via WhatsApp?", "a": "Bellen via WhatsApp is niet mogelijk bij ons."},
  {"v": "Hoe kan ik het beste een afspraak maken bij Totaal VvE Beheer?", "a": "Bellen voor afspraken is het beste via onze telefonische ondersteuning. Wij zijn bereikbaar op maandag tot en met vrijdag tussen 09.00 en 13.00 uur op het telefoonnummer 070 360 3443."},
  {"v": "Is gevolgschade standaard opgenomen in een offerte?", "a": "Gevolgschade is niet standaard inbegrepen in de offerte."},
  {"v": "Is het mogelijk om via WhatsApp contact te houden met de beheerder voor snelle afstemming?", "a": "Nee, het is niet mogelijk om via WhatsApp contact te houden voor afstemming."},
  {"v": "Wat kan ik doen als er tijdens de vergadering voldoende stemmen zijn, maar er naar mijn mening geen gewenst besluit wordt genomen?", "a": "Mocht er een besluit worden genomen waar u het niet mee eens bent, dan heeft u altijd de mogelijkheid om zelf de stap richting de kantonrechter te zetten voor een vervangende machtiging."},
  {"v": "Hoe gaan we om met een MJOP waarin nog punten staan die opgelost moeten worden, zonder dat er direct een volledig nieuw MJOP opgesteld hoeft te worden?", "a": "Het meest praktisch is om een fotodocument aan te leveren van de opgeloste punten. Dit kan vervolgens als aanvulling bij het MJOP worden gevoegd."},
  {"v": "Wanneer wordt er gekozen voor het volledig vervangen van een kozijn in plaats van alleen schilderen?", "a": "Een kozijn wordt volledig vervangen wanneer de staat van het houtwerk dusdanig slecht is dat reparatie of schilderwerk niet meer volstaat, bijvoorbeeld als het kozijn loskomt of ernstig is aangetast."},
  {"v": "Hoe verloopt de procedure bij het overstappen naar een andere bankrekening voor de VvE?", "a": "Er wordt een nieuwe bankrekening aangevraagd. Zodra deze bekend is, worden de eigenaren geïnformeerd met het verzoek om vanaf de volgende maand naar dit nieuwe rekeningnummer te betalen. Vervolgens wordt het saldo van de oude rekening overgeboekt naar de nieuwe rekening en wordt de oude rekening gesloten."},
  {"v": "Wat moet ik doen als een internetprovider (zoals KPN) weigert installatiedocumenten of een technisch rapport van de glasvezelaanleg naar de VvE te sturen?", "a": "De installateur hoort een plaatsingsdocument te kunnen verzorgen voor de VvE. Een andere optie is om te kiezen voor een professionele partij die wel bereid is de nodige documentatie en toestemmingsrapporten te delen."},
  {"v": "Is het toegestaan voor lekdetectiebedrijven om vanuit ramen aan de buitengevel te werken?", "a": "Dit dient met het lekdetectiebedrijf afgestemd te worden. Er is een grote kans dat zij in verband met ARBO-wetgeving niet uit ramen mogen hangen voor werkzaamheden aan de buitenzijde."},
  {"v": "Wat kan de oorzaak zijn van condensvorming op de ramen bij een appartement?", "a": "Hoewel gebreken aan de gevel (zoals openstaande voegen) een rol kunnen spelen, kan condensvorming op ramen ook veroorzaakt worden door slecht ventileren."},
  {"v": "Heb ik toestemming nodig van de VvE voor het plaatsen van een pergola?", "a": "Of er toestemming nodig is, hangt af van de situatie. Het is belangrijk om te weten of de pergola aan de gevel of andere gemeenschappelijke zaken wordt bevestigd. Daarnaast spelen de afmetingen een rol en of het bouwwerk volgens de gemeentelijke richtlijnen vergunningsplichtig is. Dien daarom altijd een concreet voorstel in bij de VvE-beheerder, zodat deze kan beoordelen of er toestemming gevraagd moet worden of dat er aanvullende informatie nodig is."},
  {"v": "Wie is er verantwoordelijk voor het opvolgen van garantieverzoeken bij een zelf aangedragen partij door de VvE?", "a": "Wanneer er garantieverzoeken liggen bij een door de VvE zelf aangedragen partij, ligt de verantwoordelijkheid voor het oplossen en het versturen van herinneringen bij de eigenaren zelf."},
  {"v": "Met wie moet ik contact opnemen voor advies over particuliere verzekeringen?", "a": "Wanneer we het over particuliere verzekeringen hebben, dan verwijzen we altijd naar de eigen verzekeringsadviseurs."},
  {"v": "Welke bedrijven kunnen benaderd worden voor het verhelpen van bruinrot/vochtproblemen in de kruipruimte?", "a": "U kunt hiervoor contact opnemen met gespecialiseerde bedrijven zoals Den Heijer Vochtwering of NooitmeerZwam. Bij het opvragen van informatie kunt u vermelden dat de uiteindelijke opdracht zeer waarschijnlijk via de VvE zal lopen."},
  {"v": "Is het mogelijk om op korte termijn een VvE-vergadering in te plannen voor de goedkeuring van plannen zoals het uitbreiden van een groepenkast of het plaatsen van warmtepomp-units?", "a": "Het is mogelijk om plannen voor bijvoorbeeld de uitbreiding van een groepenkast of de installatie van warmtepomp-units op papier te zetten en middels een schriftelijke stemming aan de leden voor te leggen. Op deze manier kan er wellicht akkoord worden gegeven zonder dat er een extra fysieke vergadering hoeft plaats te vinden, wat de VvE kosten voor een extra vergadering kan besparen."},
  {"v": "Wat is de beste aanpak wanneer de VvE een aanschrijving van de gemeente ontvangt voor noodzakelijk onderhoud?", "a": "Bij een aanschrijving vanuit de gemeente is het essentieel om direct in contact te treden met de gemeente of de betreffende instantie (zoals de pandbrigade). Door actieve communicatie te onderhouden en aan te tonen dat de VvE voortgang boekt met de uitvoering van de vereiste werkzaamheden, kan de preventie van definitieve dwangsommen worden bewerkstelligd."},
  {"v": "Hoe moet de VvE omgaan met een illegaal dakterras of bouwwerk op het gezamenlijke dak?", "a": "In het geval van een onrechtmatig geplaatst bouwwerk, zoals een dakterras of schuurtje, dient eerst te worden achterhaald welke eigenaar hier gebruik van maakt. Vervolgens is de eerste stap om de betreffende eigenaar dwingend aan te schrijven. In de basis is dergelijke problematiek op dat moment een verantwoordelijkheid van de eigenaar en (nog) niet direct een probleem voor de VvE als geheel."},
  {"v": "Kan de VvE-beheerder het aanbrengen van vogelwering organiseren?", "a": "Het organiseren van vogelwering behoort niet tot de standaard werkzaamheden van de beheerder. Wanneer er een offerte voor dergelijke voorzieningen wordt ontvangen, kan deze aan de vergadering van eigenaren worden voorgelegd. Indien andere eigenaren hier geen belang bij hebben, kan het zijn dat er een toestemmingsverzoek moet worden ingediend zodat u deze voorzieningen voor eigen rekening mag aanleggen."},
  {"v": "Waar moet men rekening mee houden bij de renovatie van een stenen portiektrap?", "a": "Bij de renovatie van een portiektrap moet er rekening mee worden gehouden dat achter de stenen treden vaak een houten skeletbouw zit. Zodra de treden worden weggehaald, bestaat de kans dat het onderliggende houtwerk aangetast of rot is en vernieuwd dient te worden."},
  {"v": "Moeten bewoners thuis zijn voor werkzaamheden aan de granito vloer in de gemeenschappelijke ruimtes als er bij hen binnen niets gedaan wordt?", "a": "In principe is er voor werkzaamheden aan de granito vloer in de gemeenschappelijke ruimtes alleen toegang beneden in de centrale hal of entree nodig."},
  {"v": "Hoe moet ik handelen bij zaken die enkel de appartementen van de direct betrokken eigenaren aangaan?", "a": "Bij zaken die feitelijk alleen de betreffende appartementen aangaan, wordt geadviseerd om eerst afstemming te zoeken tussen de betrokken eigenaren onderling."},
  {"v": "Worden werkzaamheden aan kozijnankers in de gevel gezien als gemeenschappelijk onderhoud of als individuele kosten?", "a": "Wanneer kozijnankers behandeld of vervangen moeten worden voor een goede afronding van noodzakelijk gevelwerk, dienen deze als onderdeel van de gemeenschappelijke gevelwerkzaamheden gezien te worden."},
  {"v": "Wanneer is een meerderheid van 80% van de stemmen vereist en wat is de procedure bij een splitsingsakte?", "a": "Een meerderheid van 80% van de stemmen is vereist voor het aangaan van leningen en voor aanpassingen van de splitsingsakte. Bij een aanpassing van de splitsingsakte is het vervolgens van belang dat alle eigenaren de aanpassing ondertekenen bij de notaris; dit kan ook via een volmacht."},
  {"v": "Hoeveel stemmen zijn er nodig voor een besluit over offertes en het vaststellen van een eenmalige extra bijdrage?", "a": "Besluiten over offertes en het vaststellen van eenmalige extra bijdrage(n) gebeurt met een meerderheid van de stemmen."},
  {"v": "Wat moet ik doen bij een lekkage of verstopping aan de standleiding van het complex?", "a": "Wanneer er sprake is van een lekkage of verstopping in de standleiding, dient u dit zo snel mogelijk te melden bij de beheerder (buiten kantoortijden via het noodnummer). Totaal VvE Beheer zal vervolgens een rioolservice of aannemer inschakelen om het probleem te verhelpen. Houd uw contactgegevens bij de hand voor het inplannen van een afspraak."},
  {"v": "Wanneer wordt een waterleiding als individueel beschouwd in een VvE?", "a": "Wanneer een leiding vanaf de individuele watermeter loopt en alleen dienstbaar is aan het betreffende appartement, wordt deze als individueel beschouwd."},
  {"v": "Is schade aan de portiektrap als gevolg van onjuist gebruik door bewoners (zoals het overmatig gieten van water) gedekt door de verzekering?", "a": "Schade die ontstaat door onjuist handelen van gebruikers, zoals het overmatig gieten van water over de trap, wordt doorgaans niet aangemerkt als verzekeringswerk. De kosten voor herstel van dergelijke schade vallen niet onder de verzekering."},
  {"v": "Is de financiële situatie van een VvE van invloed op de verantwoordelijkheid van de leden voor het onderhoud?", "a": "De financiële situatie van de VvE staat volledig los van de verantwoordelijkheid van de leden om het onderhoud te verzorgen."},
  {"v": "Welke rol speelt de beheerder bij de aanleg van glasvezel en de technische schouw?", "a": "Voor de aanleg van glasvezel dient u zelf de afspraken te organiseren met de glasvezelleverancier. De beheerder bemiddelt hier niet in. Na ontvangst van het schouwrapport wordt deze uitsluitend ter goedkeuring aan de leden voorgelegd."},
  {"v": "Met wie kan ik contact opnemen voor de status van reparaties of dossiers die via de verzekering lopen?", "a": "U kunt hiervoor het beste contact opnemen met uw beheerder. Zij kunnen u verder helpen of namens de vereniging contact opnemen met de verzekeraar."},
  {"v": "Hoe wordt de berekening van de maandbijdragen bepaald?", "a": "De berekening van de maandbijdragen bestaat uit de vaste kosten uit de begroting plus het gemiddelde uit het Meerjarenonderhoudsplan (MJOP), berekend per appartement per maand. In het kader van de wet verbetering functioneren VvE is het vaststellen van deze bijdrage op basis van een MJOP wettelijk verplicht."},
  {"v": "Is het mogelijk om rapporten of documenten als fysiek exemplaar (hard copy) te ontvangen?", "a": "Wij ontvangen en verstrekken de stukken alleen digitaal."},
  {"v": "Wanneer kan er een offerte worden opgesteld voor werkzaamheden in de kruipruimte?", "a": "Zodra de kruipruimte leeggehaald en toegankelijk is, kan een partij de situatie bekijken om hiertoe een offerte op te stellen."},
  {"v": "Is het mogelijk om naast een offerte voor houtrotherstel ook een offerte op te laten stellen voor het volledig vervangen van kozijnen?", "a": "Het is mogelijk om een aanvullend verzoek in te dienen om ook een prijsopgave op te laten stellen voor de volledige vervanging van de kozijnen."},
  {"v": "Waar moet ik op letten als de VvE een opstalverzekering heeft met een lagere dekking voor eigenarenbelang?", "a": "Het is raadzaam voor alle eigenaren om de eigenarenbelang dekking binnen de particuliere pakketten (of zakelijke pakketten in geval van verhuur) goed na te kijken."},
  {"v": "Wanneer wordt er gestart met werkzaamheden of renovaties nadat er offertes zijn opgevraagd?", "a": "De planning voor werkzaamheden volgt doorgaans op een vast proces: eerst worden de benodigde gelden geïncasseerd en vervolgens worden de definitieve offertes opgevraagd voordat er een concrete planning kan worden gemaakt."},
  {"v": "Is er sprake van garantie op werkzaamheden die niet in de oorspronkelijke offerte of het MJOP zijn opgenomen?", "a": "Op zaken waar niet aan gewerkt is, zit geen garantie. Indien bepaalde gebreken nog in goede staat waren tijdens de opname van het MJOP en niet zijn opgenomen in de uitgevoerde offerte, vallen deze niet onder de garantiebepalingen van die specifieke werkzaamheden."},
  {"v": "Is voor een keuring van de elektrische installaties binnen de VvE een Scope 8 rapport voldoende, of is een Scope 10 rapport vereist?", "a": "Voor de keuring van elektrische installaties wordt doorgaans een SCOPE 10 inspectie verwacht, aangezien deze specifiek gericht is op brandveiligheid van elektrische materieel, in tegenstelling tot de algemene veiligheidsinspectie van een SCOPE 8."},
  {"v": "Wat doet de beheerder als een Vereniging van Eigenaren (VvE) wordt overgenomen met achterstallig onderhoud?", "a": "Bij de start van het beheer wordt direct geëvalueerd welke onderhoudswerkzaamheden prioriteit hebben. Er worden offertes opgevraagd bij verschillende partijen en deze worden ter besluitvorming voorgelegd aan de Algemene Ledenvergadering (ALV)."},
  {"v": "Hoe kan ik zien of een specifiek bericht in een algemene mededeling voor mij bedoeld is?", "a": "Als een bericht specifiek voor een bepaalde eigenaar is bedoeld, wordt dit aangegeven met @naam eigenaar voor het betreffende tekstdeel."},
  {"v": "Wanneer kan ik uit een VvE stappen?", "a": "Uit de VvE stappen kan alleen bij de verkoop van het appartement."},
  {"v": "Ben ik als nieuwe eigenaar verantwoordelijk voor spullen of afval die een vorige eigenaar heeft achtergelaten in gemeenschappelijke ruimten of kruipruimtes?", "a": "Als rechtsopvolger ben je verantwoordelijk voor de staat van de ruimtes die bij het appartement horen, inclusief eventueel achtergelaten spullen of afval. Eventuele kosten of benodigde acties hiervoor dienen zelf verhaald te worden op de vorige eigenaar als u van mening bent dat dit niet door u is veroorzaakt."},
  {"v": "Komt de beheerder altijd op locatie kijken bij meldingen van overlast of schade?", "a": "De beheerder doet het beheer en bestuur in principe vanaf afstand en gaat in de regel niet zelf op locatie kijken. Er wordt gewerkt met de input van de eigenaren. Indien een verzoek concreter gemaakt moet worden, kan er gevraagd worden om foto's of andere bewijsstukken aan te leveren."},
  {"v": "Wat is de rol van de beheerder bij schadevergoedingen tussen buren of aangrenzende panden?", "a": "Wanneer er schade is ontstaan (of mogelijk nog meer schade zou kunnen ontstaan), dan wordt van de bestuurder verwacht dat deze de betreffende eigenaar (of de rechtsopvolger van de betreffende veroorzaker) aanschrijft voor die schade. Het is vervolgens aan de eigenaar in hoeverre dit weer op een vorige eigenaar te verhalen valt."},
  {"v": "Hoe gaat de VvE om met herstelwerkzaamheden aan balkons waarvoor een vergunningstraject nodig is en waarbij gedreigd wordt met dwangsommen door de handhavende instantie?", "a": "Wanneer er sprake is van handhaving, voert de VvE de communicatie met de betreffende instantie. Indien er voortgang wordt geboekt, bijvoorbeeld door het opnieuw opstarten van een vergunningstraject voor herstelwerkzaamheden via de VvE, wordt er in de regel uitstel verleend voor het toepassen van dwangsommen."},
  {"v": "Is juridische hulp bij aansprakelijkheidstellingen inbegrepen in de standaard beheersovereenkomst?", "a": "Het begeleiden van een aansprakelijkheidsstelling of juridische zaak tegen een externe partij valt niet onder de standaard beheersovereenkomst. De vergadering van eigenaars dient hiervoor een specifiek budget vast te stellen en te bepalen wie dit proces zal begeleiden."},
  {"v": "Is het mogelijk om als VvE een leningstraject aan te gaan voor het financieren van projecten?", "a": "Een leningstraject voor de VvE kan eventueel een optie zijn, mits alle betrokkenen hierin mee gaan. Wij kunnen hiervoor een offerte opstellen voor de begeleiding, aangezien dit een tijdrovend traject betreft."},
  {"v": "Is het toegestaan om vloerverwarming te plaatsen in een appartement binnen de VvE?", "a": "Indien dit niet specifiek in het Huishoudelijk Reglement (HHR) is opgenomen, dient u de juiste procedures en toestemmingsverzoeken te volgen. Wanneer een verzoek netjes en goed onderbouwd wordt aangeleverd bij het bestuur, is de inschatting dat hier doorgaans geen bezwaar tegen zal zijn."},
  {"v": "Wanneer kan er een opdracht worden verstrekt aan een herstelbedrijf na een gedekte schade?", "a": "Zodra de schade-expert een raming heeft opgesteld en de verzekeraar een definitieve bevestiging voor de uitbetaling heeft afgegeven, kan de opdracht aan het herstelbedrijf worden verstrekt."},
  {"v": "Kan de VvE ondersteunen bij een inspectie of aanschrijving die niet direct aan de VvE is gericht, maar aan een individuele eigenaar?", "a": "Wanneer een inspectie of aanschrijving van een overheidsinstantie (zoals de pandbrigade) geen aanschrijving aan de VvE zelf betreft, kan de VvE beheerder hier niets in betekenen. De eigenaar dient in dat geval zelf afspraken te maken met de betreffende instantie om eventuele last te voorkomen."},
  {"v": "Kan ik als aankoopmakelaar of externe partij financiële informatie over een VvE opvragen voor de financiering van een koper?", "a": "Gegevens van de VvE kunnen niet direct aan derden worden verstrekt. Wij verzoeken u deze informatie op te vragen via de verkopende partij (de huidige eigenaar)."},
  {"v": "Is een akkoord via WhatsApp voldoende voor het verstrekken van een opdracht voor een (nood)reparatie?", "a": "Hoewel een noodoplossing via een WhatsApp-bericht akkoord kan worden bevonden, dient dit alsnog schriftelijk via een reactie op de e-mail officieel akkoord bevonden te worden. Wij kunnen anders de opdracht niet verstrekken. Een printscreen van een WhatsApp-bericht is niet voldoende voor de dossiervorming."},
  {"v": "Wat moet ik doorgeven als er een nieuwe levering voor een aansluiting moet worden aangevraagd na een eindstand?", "a": "Om een nieuwe levering aan te vragen hebben wij de meterstand nodig, samen met de aansluitgegevens die terug te vinden zijn op de jaarrekening of een factuur."},
  {"v": "Welke gegevens heeft de VvE-beheerder nodig bij het overnemen van de nutscontracten (gas, elektra, water)?", "a": "Voor het overnemen en verwerken van gezamenlijke nutscontracten door de VvE zijn per meter de volgende gegevens nodig: de jaarnota, de meest recente factuur en de actuele meterstanden. Daarnaast dient aangegeven te worden welke huisnummers de meters delen en of de huidige contracten een variabele of vaste looptijd hebben."},
  {"v": "Wat gebeurt er als het saldo van de reserve van de VvE niet toereikend is voor noodzakelijk onderhoud?", "a": "Wanneer het saldo van de reserve niet toereikend is voor het uitvoeren van noodzakelijk onderhoud (wanneer hiertoe wordt besloten door de vergadering), dan zal er door de eigenaren aanvullend ingelegd dienen te worden conform breukdeel."},
  {"v": "Wat is de procedure als een voordeur of kozijn vervangen moet worden en de maten onbekend zijn?", "a": "Het beste is om een vakman een offerte op te laten stellen die aan de vergadering kan worden voorgelegd. Hierbij is het raadzaam om ook foto's van de huidige situatie mee te sturen."},
  {"v": "Nemen jullie schademeldingen aan die rechtstreeks door huurders worden gedaan?", "a": "Meldingen van huurders nemen wij niet aan. Bij een individueel appartement dient de huurder eerst contact op te nemen met de eigenaar van het appartement."},
  {"v": "Vanaf welk moment kan Totaal VvE Beheer informatie verstrekken of actie ondernemen voor een potentiële koper?", "a": "Pas op het moment dat u daadwerkelijk belanghebbende (eigenaar) bent, kunnen wij informatie verstrekken of zaken voor u nagaan."},
  {"v": "Kan de VvE-beheerder bemiddelen bij het verkrijgen van handtekeningen of toestemming van andere eigenaren voor een verbouwing (zoals een dakopbouw) voordat ik de woning heb aangekocht?", "a": "Pas op het moment dat u belanghebbende (eigenaar) bent, kunnen wij dingen voor u betekenen of zaken nagaan."},
  {"v": "Moet er voor het schilderen van boeiboorden altijd een steiger worden geplaatst?", "a": "Voor het schilderen van het boeiboord zal doorgaans een steiger nodig zijn. Het is raadzaam om te beoordelen of dit gecombineerd kan worden met ander onderhoud, hoewel het soms verstandiger is om schilderwerk naar voren te halen om houtrot en daarmee toekomstige hogere kosten te voorkomen."},
  {"v": "Wat kan ik doen als er geen actuele meterstanden bekend zijn of als de slimme meter niet goed lijkt te werken?", "a": "Het is mogelijk dat er een slimme meter aanwezig is, maar dat er problemen zijn met de meter. U kunt in dat geval contact opnemen met het nationale storingsnummer op telefoonnummer 0800-9009. U komt dan uit bij de netbeheerder en zij kunnen eventueel een schouw uitvoeren."},
  {"v": "Worden overdrachten uitgevoerd door de beheerders zelf?", "a": "Overdrachten worden niet door de beheerders zelf uitgevoerd."},
  {"v": "Hoeveel offertes zijn er nodig voor een schadeclaim bij de verzekeraar?", "a": "Voor de verzekeraar is één herstelofferte voldoende."},
  {"v": "Waar moet op gelet worden bij het combineren van verschillende werkzaamheden waarbij steigers nodig zijn?", "a": "Bij het combineren van werkzaamheden, zoals kozijnvervanging en gevelwerk, is het verstandig om te kijken of partijen van elkaars steigers gebruik kunnen maken. Het is belangrijk om vooraf duidelijk op papier te zetten welke partij de steiger plaatst en of andere partijen hierop kunnen 'meeliften', aangezien dit aanzienlijk in de kosten kan schelen."},
  {"v": "Hoe moeten facturen van aannemers worden geadresseerd aan de VvE?", "a": "Facturen dienen correct te worden geadresseerd aan de naam van de VvE zelf, en niet aan de beheerder."},
  {"v": "Zit de begeleiding van verhaals- en aansprakelijkheidsstellingen in de standaard dienstverleningsovereenkomst?", "a": "Nee, verhaals- en aansprakelijkheidsstellingen (inclusief de begeleiding hiervan) zitten niet in onze standaard dienstverleningsovereenkomst."},
  {"v": "Hoe kunnen besluiten over offertes worden genomen als niet alle eigenaren reageren?", "a": "Indien nodig kan er een extra vergadering worden georganiseerd. Besluitvorming kan dan plaatsvinden met een meerderheid van stemmen, eventueel via volmachten. Daarnaast wordt van eigenaren verwacht dat zij zelf ook contact opnemen met mede-eigenaren die niet reageren op correspondentie om de voortgang te bevorderen."},
  {"v": "Kan een derde partij of buurman die geen lid is van de VvE een verzoek indienen om een vergadering uit te schrijven?", "a": "Verzoeken om vergaderingen uit te schrijven kunnen enkel door de leden (eigenaren) zelf worden ingediend. Verzoeken van derden kunnen niet in behandeling worden genomen aangezien de beheerder uitsluitend voor de leden van de betreffende VvE werkt."},
  {"v": "Waar kan ik een officiële klacht indienen over het functioneren van de VvE-beheerder?", "a": "Klachten kunnen worden gemaild naar het daarvoor bestemde e-mailadres van de organisatie."},
  {"v": "Kan een voorstel voor een kleine verbetering aan het gebouw (zoals een fietsgoot) binnen het mandaat van de beheerder worden opgepakt als er een meerderheid van stemmen is binnen de VvE?", "a": "Wanneer er voor een dergelijke klus formeel geen mandaat is, is het verzoek om het voorstel op papier te zetten. Dit voorstel wordt vervolgens aan de vergadering voorgelegd met het verzoek om binnen een week eventuele bezwaren aan te geven. Indien er geen bezwaren binnenkomen, kan er vanuit worden gegaan dat het voorstel akkoord is en kan het verder worden opgepakt."},
  {"v": "Wat moet ik doen bij een hardnekkige lekkage waarvan de oorzaak onduidelijk is, en kan er lekdetectie worden ingezet?", "a": "U kunt een afspraak maken met een lekdetectiebedrijf om de bron van de lekkage te achterhalen. Wanneer uit het onderzoek blijkt dat de oorzaak van de lekkage een gemeenschappelijke gedeelte van de VvE betreft, zal de beheerder de kosten binnen het mandaat afwikkelen."},
  {"v": "Wat moet ik doen als er water op het dak blijft staan en de afvoer niet goed werkt?", "a": "Wanneer er water op het dak blijft staan door een mogelijk defecte afvoer, schakelen wij een rioolservice in om dit te verhelpen. Voor de toegang tot het dak is het vaak het makkelijkst als dit via een balkon kan plaatsvinden."},
  {"v": "Met welke richtlijnen moet ik rekening houden bij aanpassingen aan het aangezicht van het pand?", "a": "Bij voorstellen die het aangezicht van de VvE betreffen, dient er rekening gehouden te worden met de huidige kleurstellingen en de uniforme uitstraling van het gebouw."},
  {"v": "Vallen afvoer- en sanitairleidingen onder de gemeenschappelijke delen of de individuele zaken van een eigenaar?", "a": "Afvoer- en sanitairleidingen behoren tot de individuele zaken van een eigenaar, tenzij deze specifiek in de akte als gemeenschappelijk zijn aangemerkt."},
  {"v": "Faciliteert de beheerder het organiseren van toestemming voor individuele eigenaren die wijzigingen willen realiseren?", "a": "Het organiseren van toestemming voor zaken die een eigenaar wil gaan realiseren is niet iets wat wij faciliteren. Dat is aan de eigenaar die eea wil gaan realiseren."},
  {"v": "Welk bedrijf kan ik benaderen voor het bestrijden van ongedierte, zoals een wespenplaag?", "a": "U kunt hiervoor bijvoorbeeld Raco benaderen: https://racoplaagdierbestrijding.nl/contact/ of Kloek ongediertebestrijding."},
  {"v": "Hoe worden eventuele achterstanden verrekend bij de verkoop van mijn woning?", "a": "Achterstanden worden vanzelf via de afrekening met de notaris verrekend, hiervoor is geen verdere actie nodig."},
  {"v": "Wat kan ik doen als een bewoner niet meewerkt aan het verhelpen van een lekkage of schade?", "a": "In situaties waarbij een bewoner niet meewerkt aan het verhelpen van een gebrek, kan deze aansprakelijk worden gesteld en formeel worden gesommeerd om medewerking te verlenen. Daarnaast kunnen huurders melding maken bij de pandbrigade van de gemeente als de veiligheid of leefbaarheid in het geding is."},
  {"v": "Wat moet ik doen als ik niet akkoord ga met de door de beheerder aangedragen offertes?", "a": "Indien u van mening bent dat de door ons aangedragen offertes niet akkoord zijn, kunt u zelf een derde offerte (en eventuele verdere offertes) verzorgen. Wij zullen deze vervolgens ter besluitvorming voorleggen na ontvangst."},
  {"v": "Waarom zijn er nog gaatjes zichtbaar na een behandeling tegen houtworm?", "a": "Keurders vermelden altijd dat er gaten zijn; hieraan kan de klant zien wanneer het behandeld is. In het geval van een recente bestrijding is het middel nog werkzaam, ook al zijn de oude gaatjes nog zichtbaar."},
  {"v": "Kan de VvE een verklaring opstellen waaruit blijkt dat bewoners geen toegang hebben tot parkeren op eigen terrein ten behoeve van een parkeervergunningsaanvraag?", "a": "Vraag bij uw beheerder een verklaring op die bevestigd dat u geen toegang heeft tot een parkeerplaats op het eigen terrein."},
  {"v": "Wat zijn de mogelijkheden en aandachtspunten voor het plaatsen van een muuranker voor een bakfiets?", "a": "Voor het plaatsen van een muuranker zijn er een aantal aandachtspunten. In eerste instantie dient er toestemming te worden gegeven door de eigenaar van de betreffende muur of afscheiding. Verder dient er bij de gemeente te worden nagegaan in hoeverre het trottoir van de gemeente hiervoor gebruikt mag worden."},
  {"v": "Op welke manieren kan herstel van schade na een lekkage worden afgehandeld via de verzekering?", "a": "Bij schadeherstel na een lekkage zijn er doorgaans twee opties via de verzekeraar: u kunt zelf een herstelofferte aanleveren ter beoordeling, of u kunt kiezen voor herstel in natura, waarbij de verzekeraar het herstel direct laat uitvoeren."},
  {"v": "Wie kan ik bellen voor informatie over het inplannen van een afspraak met de loodgieter bij een urgente verstopping?", "a": "U kunt zelf contact opnemen met het opgegeven telefoonnummer van de Rioolservice om te informeren naar de planning."},
  {"v": "Wat gebeurt er als een eigenaar of huurder niet aanwezig is bij een geplande afspraak met een onderhoudspartij?", "a": "Indien er sprake is van een 'no-show' en het ingeschakelde bedrijf hiervoor een factuur stuurt, zal de VvE-beheerder deze kosten doorbelasten aan de betreffende eigenaar."},
  {"v": "Met welk doel worden de maandelijkse VvE-bijdragen verhoogd naar een niveau dat aanzienlijk hoger is dan voorheen?", "a": "De verhoging van de maandelijkse bijdrage is noodzakelijk om volledig aan de geldende wetgeving te voldoen."},
  {"v": "Is het verstandig om afwezig te zijn bij een vergadering (of geen volmacht te geven) als ik besluiten wil kunnen aanvechten?", "a": "Niet (via volmacht) aanwezig zijn op een vergadering waarvan u besluiten wilt aanvechten wordt meestal afgeraden. Rechters wegen de aanwezigheid van eigenaren vaak mee in hun besluiten over het aanvechten van vergaderbesluiten."},
  {"v": "Hoe moet er gehandeld worden bij een gebrek aan een gemeenschappelijk deel van het complex?", "a": "U kunt het gebrek melden bij de beheerder. Indien er herstelwerkzaamheden nodig zijn, kan de beheerder een gespecialiseerd bedrijf inschakelen om een afspraak te maken voor inspectie of herstel. Het is ook toegestaan dat de bewoner/huurder dit zelf organiseert, mits de offerte vooraf ter goedkeuring aan de beheerder wordt overlegd."},
  {"v": "Welke bedrijven kunnen worden ingeschakeld voor rioolservice of het verhelpen van verstoppingen?", "a": "U kunt hiervoor bijvoorbeeld contact opnemen met ABC Rioolservice Haaglanden, Rioolservice de Lange, Zegwaard of RRS."},
  {"v": "Wat gebeurt er met de dekking als de garantie tegen onderverzekering afloopt voordat een nieuw voorstel is ontvangen?", "a": "Wanneer er een nieuw voorstel voor de verlenging van de garantie tegen onderverzekering in aanvraag is, blijft de garantie in de tussenliggende periode van kracht, ook als het voorstel na de feitelijke afloopdatum wordt ontvangen."},
  {"v": "Blijft de Garantie tegen Onderverzekering (GTO) van toepassing als de herberekening nog niet heeft plaatsgevonden?", "a": "Zolang de Garantie tegen Onderverzekering (GTO) doorloopt tot het moment van herberekening, is dit akkoord. De GTO blijft in voorkomende gevallen van toepassing tot het moment dat de herberekening is afgerond."},
  {"v": "Kan een externe partij, zoals een taxateur, rechtstreeks documenten of informatie opvragen bij de VvE beheerder?", "a": "Wij werken alleen voor eigenaren. Een externe partij kan de eigenaar verzoeken om de benodigde documenten bij ons op te vragen of de eigenaar kan ons toestemming geven om de verzoeken van een externe partij in behandeling te nemen."},
  {"v": "Wat zijn de reguliere openingstijden van het kantoor?", "a": "Het kantoor is geopend van maandag tot en met vrijdag van 9.00 tot 17.00 uur."},
  {"v": "Wie is verantwoordelijk voor het repareren van de oorzaak van een schade binnen de VvE?", "a": "Het is de verantwoordelijkheid van de VvE of de individuele eigenaar om de oorzaak van een schade te repareren."},
  {"v": "Welke mogelijkheden zijn er voor het herstellen van gevolgschade nadat een schadeclaim is goedgekeurd door de verzekeraar?", "a": "Er zijn twee mogelijkheden voor het herstellen van gevolgschade als de schade verzekerd is: u kunt de schade laten repareren door een door u gekozen bedrijf (waarbij de verzekeraar vooraf graag een gespecificeerde offerte ontvangt) of de verzekeraar schakelt een met hen samenwerkend bedrijf in voor direct herstel."},
  {"v": "Kan Totaal VvE Beheer tijdens mijn vakantie correspondentie doorsturen naar een tijdelijke contactpersoon?", "a": "Nee, de beheerder verzorgt geen automatische doorsturing van e-mail naar derden tijdens uw vakantie. U dient zelf uw mailbox bij te houden of in te stellen dat e-mail automatisch wordt doorgestuurd naar de gewenste persoon."},
  {"v": "Wat wordt er verwacht van de bewoners wanneer er onderhoud aan de lift plaatsvindt?", "a": "Er moet voor gezorgd worden dat de monteur opgevangen wordt en dat hij/zij toegang heeft tot de lift en bijbehorende ruimtes (bijvoorbeeld door het beschikbaar stellen van sleutels indien van toepassing)."},
  {"v": "Wat gebeurt er als er bij een stemming over onderhoud aan een gezamenlijk bouwdeel (zoals een portiekkozijn) geen unaniem akkoord wordt bereikt door de eigenaren?", "a": "Wanneer er geen unaniem akkoord volgt, is het aan de eigenaren wat ze ermee willen doen, zoals bijvoorbeeld het aanvragen van een aanschrijving bij de gemeente."},
  {"v": "Hoe kunnen plannen voor verbeteringen aan het pand, zoals het afsluiten van een portiek, in gang worden gezet?", "a": "Dergelijke zaken moeten worden besproken tijdens de ledenvergadering. Dit zijn de momenten om voorstellen te bespreken en besluiten te nemen. Wanneer eigenaren met concrete voorstellen komen, kunnen deze aan de vergadering worden voorgelegd voor besluitvorming. Zonder aanwezigheid en input van eigenaren tijdens de vergadering kunnen dergelijke zaken niet in gang worden gezet en wordt de vastgestelde begroting gevolgd."},
  {"v": "Heeft Totaal VvE Beheer contactgegevens van partijen voor het onderhoud van verwarmingsketels?", "a": "Voor het servicen van verwarmingsketels kunt u contact opnemen met partijen zoals Sima of Feenstra."},
  {"v": "Wat wordt er verwacht van bewoners tijdens de opname voor een Meerjarenonderhoudsplan (MJOP)?", "a": "Tijdens de opname voor het Meerjarenonderhoudsplan (MJOP) is het de bedoeling dat bewoners thuis beschikbaar zijn, zodat de bouwkundige de situatie ter plaatse goed kan beoordelen."},
  {"v": "Onder welke algemene voorwaarden kan een VvE akkoord gaan met de installatie van een traplift in een gemeenschappelijk trappenhuis?", "a": "De installatie van een traplift kan worden goedgekeurd onder de voorwaarde dat de lift de toegang tot individuele appartementsdeuren niet blokkeert, bijvoorbeeld door de lift pas vanaf de eerste traptrede te laten starten. Daarnaast kan de eis worden gesteld dat er een smal model wordt geplaatst en dat er afspraken worden gemaakt met de leverancier over het tijdelijk verwijderen en veilig opslaan van de zitting bij langdurige afwezigheid."},
  {"v": "Wat moet de VvE doen als we een nieuwe deur of aanpassing aan de veranda willen laten uitvoeren?", "a": "Indien u een aanpassing wilt laten uitvoeren, zoals het plaatsen van een deur voor de veranda, dient u zelf één of meerdere offertes op te vragen bij relevante bedrijven en deze ter beoordeling naar de VvE beheerder te sturen."},
  {"v": "Is het verplicht voor eigenaren om aanwezig te zijn bij VvE-vergaderingen?", "a": "Het is aan de eigenaren zelf om de verantwoordelijkheid te nemen om aanwezig te zijn bij vergaderingen of niet. In principe vindt dit eenmaal per jaar plaats. Tijdens vergaderingen wordt de tijd genomen om zowel de rechten als de plichten van de eigenaren te verduidelijken."},
  {"v": "Binnen welke tijden worden de algemene ledenvergaderingen standaard gehouden en zijn hier extra kosten aan verbonden?", "a": "De tijden van de vergaderingen zijn bij ons standaard tussen 9.00 en 16.00 uur (starttijd). Wanneer een vergadering buiten deze tijden start, brengen wij aanvullend € 95,00 excl. BTW in rekening."},
  {"v": "Schakelt de opstalverzekering altijd een expert in bij schade aan een balkon?", "a": "Nee, de inschatting is dat de opstalverzekering niet in alle gevallen een expert zal inschakelen voor de beoordeling van dergelijke schades."},
  {"v": "Hoe wordt een vochtprobleem of lekkage op een balkon onderzocht als de oorzaak niet direct duidelijk is?", "a": "Bij complexe vochtuitbreiding aan de onderzijde van een balkon kan een onafhankelijk bouwkundige worden ingeschakeld voor een inspectie en beoordeling. Indien visuele inspectie onvoldoende informatie biedt, kan er een lekdetectiebedrijf worden ingezet dat met behulp van kleurstoffen de exacte bron van de lekkage probeert te achterhalen."},
  {"v": "Wat is de procedure wanneer er geld uit de gemeenschappelijke reserve wordt gebruikt voor onderhoud waar niet elke eigenaar aan hoeft mee te betalen?", "a": "Wanneer er door een specifieke groep eigenaren een bedrag uit de gemeenschappelijke reserve wordt onttrokken voor onderhoud waarvoor een andere eigenaar (bijvoorbeeld van de parterre) niet hoeft mee te betalen, is het gebruikelijk om deze eigenaar naar aandeel te compenseren."},
  {"v": "Waarom stapt de VvE over naar een andere bank (zoals ABN AMRO)?", "a": "De overstap naar een andere bank kan een kleine kostenbesparing opleveren voor de VvE. Daarnaast is het beheersysteem volledig ingericht op deze bank, wat zorgt voor een efficiëntere verwerking van de administratie."},
  {"v": "Wat moet ik doen bij een plafondlekkage die vermoedelijk bij de bovenburen vandaan komt?", "a": "De eerste stap is om bij de bovenburen te kijken of daar een duidelijke oorzaak te vinden is. Als de oorzaak bij hen ligt (zoals individueel leidingwerk of achterstallig onderhoud van de keuken of badkamer), dan is het de verantwoordelijkheid van de eigenaar van de bovenwoning om deze oorzaak weg te nemen."},
  {"v": "Wat moet ik doen als ik schade aan de gevel of het metselwerk van het pand constateer?", "a": "Wanneer u schade constateert, verzoeken wij u om foto's hiervan naar ons op te sturen. Aan de hand van deze foto's kunnen wij de situatie beoordelen en waar nodig de juiste acties in gang zetten, zoals een inspectie of het coördineren van herstelwerkzaamheden."},
  {"v": "Wat is de rol van de VvE beheerder bij het besluiten over zaken zoals het plaatsen van een portiekhek?", "a": "De beheerder legt de betreffende zaken voor aan de vergadering ten behoeve van de besluitvorming."},
  {"v": "Zijn de kosten voor een lekdetectiebedrijf gedekt door de verzekering?", "a": "In sommige gevallen is een lekdetectie gedekt door de verzekeraar, controleer dit voor de zekerheid op de polis of vraag het na bij de beheerder van de vereniging."},
  {"v": "Is er toestemming nodig van de VvE of de gemeente voor het vervangen van ramen of kozijnen?", "a": "Voor het vervangen van ramen en kozijnen is toestemming nodig van de VvE, aangezien deze over het algemeen gemeenschappelijk eigendom zijn en de VvE hier vaak gezamenlijk over beslist. Wat betreft de voorzijde van de woning is het ook belangrijk om bij de gemeente na te gaan of er een vergunning nodig is. Zodra u een concreet verzoek heeft, kunt u dit bij de VvE indienen."},
  {"v": "Is de VvE-beheerder verantwoordelijk voor de medewerking of het gedrag van huurders van eigenaren?", "a": "De VvE-beheerder is niet verantwoordelijk voor de gedragingen van huurders van individuele eigenaren en kan huurders niet dwingen om medewerking te verlenen."},
  {"v": "Kan ik individuele woningverbetering, zoals het plaatsen van dubbelglas+, vergoed krijgen via de VvE?", "a": "Hoewel dergelijke verzoeken aan de VvE kunnen worden voorgelegd, is het onwaarschijnlijk dat er akkoord wordt gegeven op een vergoeding voor individuele woningverbetering. Een dergelijke maatregel is vaker reëel wanneer dit collectief wordt uitgevoerd. In dat geval is het raadzaam om eerst bij de buren te informeren of er animo is voor een gezamenlijke aanpak."},
  {"v": "Waarom kan ik PDF-bestanden of documenten in het portaal niet goed lezen of opslaan?", "a": "Wanneer PDF-bestanden niet goed openen of leesbaar zijn, ligt dit meestal aan de instellingen van de gebruikte internetbrowser (zoals het ontbreken van extensies voor PDF-bestanden). Wij adviseren om in dat geval een andere browser te proberen om de documenten juist te kunnen inzien of op te slaan."},
  {"v": "Is het mogelijk om bestanden die in een ander formaat (zoals php) worden aangeboden om te zetten naar een PDF-bestand?", "a": "Totaal VvE Beheer heeft geen mogelijkheden om aanpassingen in het bestandsformaat van de verstrekte stukken te doen."},
  {"v": "Is het de taak van de VvE-beheerder om achtergelaten fietsen of eigendommen van derden uit de voortuin te verwijderen?", "a": "Het verwijderen van eigendommen van derden behoort niet tot de taken van de beheerder/administrateur. De beheerder is niet bevoegd om eigendommen van anderen te verwijderen. Verzoeken hiertoe dienen rechtstreeks tussen eigenaren onderling te worden geregeld en/of bij de betreffende instanties te worden gemeld."},
  {"v": "Stelt de opstalverzekering eisen aan de jaarlijkse keuring van brandmelders in appartementen?", "a": "Vanuit de opstalverzekering zijn er meestal geen eisen voor de keuring van brand/rookmelders in het geval van particuliere bewoning, voor bedrijfsruimte gelden er veelal wel preventiemaatregelen. _x000D_\n _x000D_\nDit neemt natuurlijk niet weg dat bijvoorbeeld de gemeente (of andere instantie) aan u als verhuurder aanvullende eisen kan stellen, waardoor dit wel nodig zou kunnen zijn (particuliere bewoning)."},
  {"v": "Is Totaal VvE Beheer verantwoordelijk voor de werkzaamheden die door een externe aannemer worden verricht?", "a": "Totaal VvE Beheer is niet (eerstelijns) verantwoordelijk voor werkzaamheden die door een externe partij worden verricht. De vereniging neemt zelf het besluit om werkzaamheden aan een externe aannemer te gunnen of uit te besteden. _x000D_\n_x000D_\nVoor de controle/begeleiding van de werkzaamheden kan de VvE er altijd voor kiezen voor de inzet van een (interne/externe) onafhankelijke bouwkundige."},
  {"v": "Wanneer kan er iets gezegd worden over de uitvoering van werkzaamheden nadat een opname voor offerte heeft plaatsgevonden?", "a": "Zodra de offerte is ontvangen, zal deze aan de vergadering worden voorgelegd. Pas na eventuele opdrachtverstrekking kan er informatie worden gegeven over de uitvoering van de werkzaamheden."},
  {"v": "Wat houdt een last onder dwangsom (LOD) in voor een VvE en waar kan ik hierover meer informatie vinden?", "a": "Een last onder dwangsom (LOD) is een herstelmaatregel van een bestuursorgaan (zoals de gemeente) die inhoudt dat er een sanctie wordt opgelegd als een bepaalde overtreding niet binnen een gestelde termijn wordt hersteld. Als eigenaar kunt u via het Totaal Portaal 24/7 inzicht krijgen in relevante documenten van uw VvE die hierop betrekking hebben."},
  {"v": "Op welke manier kunnen extra bijdragen voor onderhoud of renovatie worden voldaan en is betaling in termijnen mogelijk?", "a": "Betalingen van extra bijdragen dienen bij voorkeur in één keer voldaan te worden. Mocht dit niet mogelijk zijn, dan kan er contact worden opgenomen om te bespreken of er betalingsafspraken gemaakt kunnen worden. Let op: opdrachten richting aannemers kunnen pas worden verstrekt zodra het volledige bedrag op de rekening van de VvE staat. Een latere betaling (of betaling in termijnen) betekent dat het langer duurt voordat de werkzaamheden kunnen worden uitgevoerd."},
  {"v": "Wat moet ik doen bij een urgente lekkage als er geen contact mogelijk is met de buren waar de oorzaak vermoedelijk ligt?", "a": "Wanneer er sprake is van een urgente lekkage en er kan geen contact worden gelegd met de bewoners van het pand waar de lekkage vandaan komt, kunt u bij hoge urgentie de brandweer inschakelen. Voor een beoordeling door de VvE-beheerder ontvangen wij graag foto's of video's van de situatie."},
  {"v": "Wat is de verplichte minimale reserve en op welke basis wordt de bijdrage voor het reservefonds vastgesteld?", "a": "Er is geen wettelijk verplichte minimale totale reserve, maar wel een verplichte jaarlijkse reservering conform de Wet verbetering functioneren VvE. De bijdragen worden zo vastgesteld dat de jaarlijkse reservering uitkomt op minimaal 0,5% van de herbouwaarde van het gebouw, of op basis van de benodigde bedragen in een actueel Meerjarenonderhoudsplan (MJOP). De Vergadering besluit conform het reglement (artikel 14.2) op welke van deze beide wijzen de eigenaren bijdragen. Voor de 0,5% norm wordt in eerste instantie uitgegaan van een door de verzekeraar opgegeven geschatte herbouwwaarde. Vervolgens worden er taxaties uitgevoerd om de definitieve herbouwwaardes vast te stellen, welke na goedkeuring door de ALV in de begroting worden verwerkt. Deze minimale reservering is met name van belang voor kopers bij het verkrijgen van hun financiering."},
  {"v": "Kunnen parkeerkosten door aannemers als meerkosten in rekening worden gebracht bij de VvE?", "a": "Parkeerkosten (indien geen gebruik kan worden gemaakt van bezoekerspassen) zijn niet ongebruikelijk en redelijk om te voldoen. Dit zal in de meeste gevallen ook in de betreffende voorwaarden/offertes worden/zijn vermeld."},
  {"v": "Wat is de procedure als er een vermoeden van een lekkage aan een afvoer is, maar er geen actieve lekkage wordt waargenomen?", "a": "Wanneer er geen actieve lekkage wordt waargenomen, zou er gestart kunnen worden om in kaart te brengen van wie de betreffende afvoer is. Een eerste stap hierbij is om samen met de betreffende eigenaren en/of bewoners vast te stellen wat er gebeurt bij het gebruik van de betreffende afvoeren. _x000D_\nWanneer er duidelijk is welke afvoer er dan problemen geeft, dan dient de betreffende eigenaar dit voor eigen rekening te herstellen."},
  {"v": "Is een volmacht voor de eerste Algemene Ledenvergadering (ALV) ook geldig voor de tweede vergadering?", "a": "Nee, een volmacht voor de eerste vergadering gaat niet automatisch mee naar de tweede reglementaire vergadering (tenzij hier wel nadrukkelijk opmerking over is/wordt gemaakt in de betreffende volmacht)."},
  {"v": "Wat gebeurt er als een factuur het mandaat van de beheerder overschrijdt?", "a": "Wanneer een factuur boven het mandaat ligt, moet deze aan de vergadering worden voorgelegd voor akkoord. Bij het ontbreken van een unaniem akkoord wordt de factuur ter bespreking op de agenda van de eerstvolgende Algemene Ledenvergadering (ALV) geplaatst."},
  {"v": "Welke schade wordt er doorgaans door de verzekering van de VvE vergoed bij een schademelding?", "a": "Bij een schademelding wordt in de regel alleen de gevolgschade vergoed mits er sprake is van een gedekte gebeurtenis. Het herstel van de schadeoorzaak is voor VvE (tenzij dit een individuele oorzaak betreft)."},
  {"v": "Wat is de procedure als er een verzoek komt om een jaarlijkse vergoeding te betalen aan een naburige VvE voor het gebruik van gemeenschappelijke voorzieningen, zoals portiekverlichting?", "a": "Wanneer er een verzoek binnenkomt via beheerder van de buren, zal de beheerder dit verzoek formeel voorleggen aan de vergadering mbt besluitvorming/controle. Bij akkoord dit conform afspraken met de beheerder van de buren verzorgen namens de VvE."},
  {"v": "Hoe werkt het herstel van schade en de afwikkeling van het schadebedrag bij een verzekeringskwestie?", "a": "Dit is afhankelijk van de soort opstalverzekering, bijvoorbeeld of de betreffende verzekering een mogelijk voor \"direct herstel' kent . _x000D_\n_x000D_\nIn de meeste situaties dient via de beheerder een compleet dossier te worden aangeleverd, bestaande uit foto's van de schade, bevestiging wegnemen schadeoorzaak (factuur) en herstelofferte gevolgschade. _x000D_\n_x000D_\nDe opdrachtverstrekking via het herstel kan pas in gang worden gezet na goedkeuring en/of bevestiging vanuit de verzekeraar."},
  {"v": "Kunt u helpen bij het vinden van een goede en betaalbare loodgieter voor werkzaamheden in mijn appartement?", "a": "U zou Loodgietersbedrijf Rieske kunnen proberen via https://www.loodgietersbedrijf-rieske.nl/site/contact."},
  {"v": "Op welke manier vindt de besluitvorming binnen de VvE plaats over voorgestelde plannen of aanpassingen?", "a": "Plannen kunnen ter besluitvorming worden voorgelegd middels een schriftelijke stemming (unaniem akkoord nodig) of door het organiseren van een extra Algemene Ledenvergadering (ALV) waarin betreffende zaken kunnen worden besproken/besloten."},
  {"v": "Welke tenaamstelling voor de appartementseigenaren wordt er aangehouden voor de administratie van de VvE?", "a": "De tenaamstelling moeten wij conform het kadaster aanhouden."},
  {"v": "Wat moet ik doen als de opstalverzekering een schadeclaim afwijst en ik deze wil indienen bij mijn eigen aansprakelijkheidsverzekering (individuele schadeoorzaak)?", "a": "Wanneer de verzekeraar een afwijzing geeft op een schadeclaim met een individuele schadeoorzaak, dan wordt de afwijzing naar u doorgestuurd. De afwijzing kunt u dan gebruiken om een verzoek in te dienen bij de eigen aansprakelijkheidsverzekering. Wanneer deze ook niet tot uitkering overgaat, dient u de schade onderling met de betreffende partij/eigenaar af te wikkelen."},
  {"v": "Worden reparatiekosten die niet door de opstalverzekering worden gedekt, vergoed door de aansprakelijkheidsverzekering voor particulieren (AVP)?", "a": "Nee, herstelkosten van een schadeoorzaak zijn in de basis geen verzekeringswerk (maar onderhoud)._x000D_\nIn sommige gevallen kan het opsporen van een schadeoorzaak (hak- en breekwerk of de kosten van lekdetectie) wel worden ingediend."},
  {"v": "Wat is er nodig voor de goedkeuring en afwikkeling van reeds uitgevoerde werkzaamheden door een individuele eigenaar?", "a": "Voor de afrekening van een factuur (gemeenschappelijk zaak) dient er of een vergaderbesluit (met meerderheid stemmen) of een unaniem akkoord buiten de vergadering te zijn middels een schriftelijke stemming."},
  {"v": "Is de VvE verantwoordelijk voor het onderhoud of vervangen van rookgasafvoeren?", "a": "De verantwoordelijkheid voor de rookgasafvoer hangt af van het splitsingsreglement. In sommige gevallen worden ze als individueel beschouwd, terwijl ze in andere gevallen (doorgaans bij collectieve systemen of specifieke bepalingen) onder de verantwoordelijkheid van de VvE vallen."},
  {"v": "Welke subsidies zijn er beschikbaar voor het vervangen van kozijnen en glas binnen een VvE?", "a": "Dit is afhankelijk van de gemeente en de omvang van de geplande werkzaamheden, soms zijn er verschillende subsidieregelingen beschikbaar. Te denken aan rijkssubsidies (RVO) voor minimaal HR++ glas. Daarnaast kennen sommige gemeenten aanvullende subsidies voor appartementen met een lager energielabel (label D of lager)."},
  {"v": "Wat is de procedure bij een nieuwe schademelding nadat een vorig dossier is gesloten zonder de bevestiging dat de eerdere schade reeds volledig is hersteld?", "a": "In het geval van een nieuwe schade zal eerst aangetoond moeten worden dat de eerdere schade volledig is hersteld. Zonder dit bewijs kan een nieuwe schademelding niet in behandeling worden genomen."},
  {"v": "Kan ik schade al laten herstellen voordat de een expert van de verzekeraar is langsgekomen?", "a": "Zaken al laten herstellen voordat een expert de schade heeft kunnen beoordelen is volledig voor eigen rekening en risico en meestal niet verstandig. _x000D_\n_x000D_\nWanneer er toch gekozen wordt dit te doen, is het zeer dringende advies alles zo compleet mogelijk vast te leggen middels (minimaal) een fotoreportage. Wanneer een door de verzekeraar aangewezen expert de situatie niet meer goed kan beoordelen en dit problemen met de vaststelling oplevert, kan dit namelijk gevolgen hebben voor de uitkering."},
  {"v": "Wat zijn de vervolgstappen als geluidsoverlast niet onderling tussen bewoners kan worden opgelost?", "a": "Mochten eigenaren er onderling niet uitkomen, dan is het aan de betreffende eigenaar/eigenaren die geluidsoverlast ervaren om zelf de vervolgstappen te zetten (inschakelen instanties en/of juridische stappen)."},
  {"v": "Wat moet ik doen als een lekkage aan het dak opnieuw optreedt na eerdere reparaties?", "a": "Wanneer een lekkage opnieuw optreedt op een locatie waar onlangs werkzaamheden zijn uitgevoerd, zal Totaal VvE Beheer contact opnemen met de betreffende daktechnieker om te onderzoeken of de reparatie onder de garantie valt. Indien het geen garantiekwestie betreft, wordt er gewerkt met een vooraf vastgesteld mandaat voor reparatiekosten; bij overschrijding hiervan zal eerst een offerte worden opgesteld en de vergadering worden voorgelegd."},
  {"v": "Wat moet ik doen als ik vragen heb over de uitvoering van de werkzaamheden door de herstelpartij (herstelofferte)?", "a": "In geval van bijzonderheden of vragen over de uitvoering/offerte kunt u deze direct met de uitvoerder afstemmen. Mocht u hier niet uitkomen, kunt u zich bij de bestuurder melden."},
  {"v": "Worden bij herstelwerkzaamheden via de verzekering volledige plafonds of muren geschilderd?", "a": "Vanuit de verzekering worden uitsluitend beschadigde stukken vergoed. De herstelpartijen worden op deze wijze aangestuurd, wat betekent dat niet altijd complete plafonds worden aangepakt, maar enkel de direct getroffen delen."},
  {"v": "Is er sprake van verzekeringsdekking bij schade door achterstallig onderhoud?", "a": "In geval van duidelijk achterstallig onderhoud is er in principe geen dekking. De meeste polissen vereisen dat er sprake is van een onvoorziene gebeurtenis."},
  {"v": "Hoe gaat de VvE om met uitspraken over verzekeringsdekking?", "a": "Wij doen nooit uitspraken over dekking; de beoordeling hiervan is altijd aan de verzekeraar."},
  {"v": "Ik wil mijn voordeur veranderen, welke kleur mag ik aanhouden?", "a": "Aanpassingen van kleurstelling dienen altijd aan de vergadering te worden voorgelegd? Dit nog los van eventuele benodigde vergunningsaanvragen bij de gemeente."},
  {"v": "Hoe kunnen opmerkingen over uitgevoerde werkzaamheden het beste worden aangeleverd bij de beheerder?", "a": "Het is raadzaam om opmerkingen over de werkzaamheden na afronding te bundelen en deze gespecificeerd en puntsgewijs aan te leveren, bij voorkeur vergezeld van foto's per punt. Dit zorgt voor een duidelijke communicatie richting de aannemer."},
  {"v": "Hoe wordt de noodzaak van bepaalde werkzaamheden binnen de VvE bepaald?", "a": "De noodzaak van werkzaamheden is aan de vergadering om te bepalen. Dit kan door leden zelf, maar wellicht ook door het laten opstellen van een MJOP door een onafhankelijk bouwkundige die hier direct advies over uit kan brengen."},
  {"v": "Worden onderhoudsoffertes vergoed door de verzekering?", "a": "Onderhoudsoffertes (achterstallig) van een VvE worden niet gedekt door de opstalverzekering. Dit is onderhoud dat door de VvE dient uitgevoerd en bekostigd te worden. De opstalverzekering dekt schade veroorzaakt door gebeurtenissen als brand, storm, waterlekkage, inbraak en vandalisme. Ook bijkomende kosten zoals opruimkosten en expertisekosten kunnen gedekt zijn, afhankelijk van de polis."},
  {"v": "Wat zijn de mogelijkheden wanneer een aannemer weigert een gedetailleerde specificatie van een offerte aan te leveren?", "a": "Wanneer een partij niet bereid is om een verdere specificatie van de offerte aan te leveren, is het aan de VvE om te bepalen of zij wel of geen gebruik willen maken van de diensten van deze partij. Een alternatieve optie is om zelf andere partijen of offertes aan te dragen voor de gewenste werkzaamheden."},
  {"v": "Zijn de kosten voor vervanging van een laminaatvloer gedekt door de VvE-verzekering?", "a": "De kosten voor vervanging van een laminaatvloer zijn doorgaans voor rekening van de inboedelverzekeraar van de bewoner en vallen niet onder de collectieve gebouwenverzekering van de VvE."},
  {"v": "Wat kan de VvE-beheerder betekenen bij overlast van etensluchten vanuit een nabijgelegen bedrijfspand?", "a": "De VvE-beheerder kan het bericht doorzetten naar de betreffende eigenaren met het verzoek om contact op te nemen. Voor de beheerder zijn dit echter doorgaans geen zaken waar zij verder direct actie in kunnen ondernemen."},
  {"v": "Verleent de beheerder medewerking bij een eventuele overstap naar een nieuwe bestuurder of beheerder?", "a": "Indien de VvE besluit op zoek te gaan naar een nieuwe bestuurder of beheerder, zal de huidige beheerder hier alle nodige medewerking aan verlenen."},
  {"v": "Wat is de rol van de VvE-beheerder bij het aanpassen van de splitsingsakte?", "a": "De rol van de beheerder bij het aanpassen van een splitsingsakte is beperkt tot de besluitvorming. Zodra de notaris hierom verzoekt, wordt de besluitvorming gefaciliteerd op basis van een conceptakte. Voor het proces van aanpassing en formalisering dient de VvE zelf af te stemmen met een notaris."},
  {"v": "Waarom is het verstandig om een wijziging in de splitsingsakte in één keer volledig en correct door te voeren?", "a": "Het is raadzaam om een akte in één keer goed aan te passen, omdat notarissen aanzienlijke kosten rekenen voor elke afzonderlijke wijziging of aanpassing."},
  {"v": "Bij wie kan ik terecht voor het melden van glasschade en het herstellen hiervan?", "a": "U kunt hiervoor contact opnemen met de beheerder van de VvE. Er kan dan direct een afspraak worden gemaakt met de glashersteller om het glas te herstellen of te bestellen. De beheerder helpt u ook verder met het indienen van eventuele facturen. Let er wel op dat er foto's van de schade nodig zijn voor de opstalverzekering."},
  {"v": "Binnen welke termijn kan ik een reactie verwachten van Totaal VvE Beheer?", "a": "Wij streven ernaar om binnen 48 uur een reactie te geven. Indien een telefonische reactie niet mogelijk is, sturen wij een e-mail om te laten weten dat de afhandeling iets langer duurt."},
  {"v": "Worden huurders meegenomen in de officiële mailwisselingen van de VvE?", "a": "Wij communiceren uitsluitend met de eigenaar van de woning. Huurders horen door de verhuurders ingelicht te worden."},
  {"v": "Wie is verantwoordelijk voor het herstel van schade die is ontstaan door een verbouwing van een eigenaar?", "a": "In het geval er schade ontstaat door een verbouwing van een eigenaar, dan dient deze dit uiteraard (via de betreffende aannemer) te laten herstellen. U dient hiertoe altijd rechtstreeks bij de betreffende eigenaar een verzoek in te dienen."},
  {"v": "Wat zijn de nadelen van het plaatsen van een extra gemeenschappelijke meter voor de portiekverlichting?", "a": "Dat is een veel duurdere oplossing. Alleen al de leveringskosten van een extra aansluiting kosten een specifiek bedrag per maand bovenop de verbruikskosten."},
  {"v": "Welk BTW-tarief moet er gehanteerd worden voor schilder- en stucwerkzaamheden bij de VvE?", "a": "Voor schilder- en stucwerkzaamheden dient het verlaagde BTW-tarief van 9% te worden toegepast. Dit tarief geldt voor zowel de arbeids- als de materiaalkosten, inclusief voorbehandeling en afplakken."},
  {"v": "Worden schademeldingen gedeeld met de rest van de VvE?", "a": "In het kader van transparantie wordt het complete dossier dat naar de verzekering gaat ook gedeeld met de gehele VvE."},
  {"v": "Blijven de betalingsverplichtingen aan de VvE bestaan als de beheerovereenkomst wordt opgezegd?", "a": "Betalingen aan de VvE blijven staan, totdat de vergadering anders zou besluiten. De bankrekening is en blijft eigendom van de vereniging en de verplichting tot betaling blijft voor alle eigenaren hetzelfde."},
  {"v": "Hoe werkt de betaling wanneer een reparatie via de verzekering loopt en wat wordt er van de eigenaar verwacht tijdens de uitvoering?", "a": "Wanneer de werkzaamheden zijn afgerond ontvangt de beheerder de factuur van de aannemer. Deze zal bij de verzekering worden ingediend voor afronding van de betaling. De verzekeraar maakt het geld over naar de VvE bankrekening waarna de beheerder ervoor zorgt dat de factuur betaald wordt. _x000D_\nVan de eigenaar wordt enkel verwacht toegang te verlenen tot de woning voor de uitvoer van het herstel."},
  {"v": "Wat zijn de mogelijkheden als ik zelf een partij heb voor het uitvoeren van herstelwerkzaamheden binnen de VvE?", "a": "Als deze partij het herstel onder het mandaat van de VvE kan uitvoeren is dit geen probleem. Wel dienen zij bij de Kamer van Koophandel ingeschreven te staan en een officiële met BTW belastte factuur aan te kunnen leveren."},
  {"v": "Ben ik als nieuwe eigenaar verantwoordelijk voor gebreken of blokkades die door de vorige eigenaar zijn veroorzaakt?", "a": "Als rechtsopvolger neemt u eventuele problemen over die mogelijk door de verkopende partij gecreëerd zijn. Het verzoek om dergelijke problemen op te lossen blijft daarom bij de huidige eigenaar liggen."},
  {"v": "Moet zonwering worden verwijderd bij betonherstelwerkzaamheden aan de balkons?", "a": "Dat is afhankelijk van de werkzaamheden die uitgevoerd moeten worden. Het verstandigste is om dit aan desbetreffende aannemer te vragen voor de werkzaamheden gaan starten."},
  {"v": "Is het mogelijk om subsidie aan te vragen voor de isolatie bij het vervangen van het dak?", "a": "Voor isolatie bij het vervangen van het dak kan subsidie worden aangevraagd. Let wel op dat dit specifiek voor het isolatiemateriaal geldt; voor bepaalde andere materialen, zoals folie, is het niet altijd mogelijk om subsidie aan te vragen."},
  {"v": "Is het van belang dat de gevel in goede staat is voordat deze wordt geïmpregneerd?", "a": "Wanneer je een gevel wilt impregneren is het van belang dat de gevel in goede staat is en er geen zichtbare gebreken in het metselwerk zijn."},
  {"v": "Valt een barst in een binnenmuur onder de verantwoordelijkheid van de VvE?", "a": "Een scheur of barst binnen in de woning valt niet onder het gemeenschappelijke gedeelte van de VvE. U dient hiervoor zelf een partij in te schakelen, bijvoorbeeld een stukadoor."},
  {"v": "Wie kan er gebruikmaken van het noodnummer van de VvE?", "a": "Ons noodnummer is alleen te bereiken voor eigenaren. Huurders dienen zich te melden bij hun verhuurder."},
  {"v": "Wat is vaak de oorzaak van schimmelvorming onder kozijnen?", "a": "Schimmel onder de kozijnen wordt vaak niet veroorzaakt door bouwkundige gebreken aan de kozijnen zelf, maar door een gebrek aan ventilatie in de betreffende ruimte."},
  {"v": "Is het mogelijk om spouwmuurisolatie toe te passen bij een pand dat rond 1924 is gebouwd?", "a": "Bij panden die rond 1924 zijn gebouwd, werden nog geen spouwmuren gebruikt. Hierdoor is het niet mogelijk om spouwmuurisolatie toe te passen."},
  {"v": "Hoe wordt er omgegaan met offertes voor werkzaamheden die zowel VvE-gerelateerde punten als individuele punten bevatten?", "a": "In sommige gevallen kan worden besloten om zowel de VvE-gerelateerde punten als de individuele punten gezamenlijk in de offerte voor de VvE op te nemen, zodat de werkzaamheden integraal uitgevoerd kunnen worden. De kosten voor de individuele punten zullen naderhand doorbelast worden aan desbetreffende eigenaar."},
  {"v": "Bij wie kan ik nagaan of mijn woning een bijbehorende berging heeft?", "a": "Om te achterhalen of er een berging bij de woning hoort, kunt u kijken in de stukken die u heeft ontvangen bij het kopen van de woning. Ook kunt u de splitsingsakte raadplegen om te zien wat daarover benoemd staat."},
  {"v": "Is het verstandig om bij een slechte staat van het dak direct voor een grondige renovatie te kiezen in plaats van een tijdelijke reparatie?", "a": "Wanneer een dak in zeer slechte staat verkeert, is het raadzaam om de staat van het dak grondig aan te pakken in plaats van een tijdelijke reparatie uit te voeren. Een reparatie is vaak kostbaar en bij een slecht dak blijft het risico op nieuwe lekkages op andere plekken bestaan. Het is verstandig om eerst een dakonderzoek of uitgebreide inspectie te laten uitvoeren en meerdere offertes te vergelijken om een weloverwogen keuze te kunnen maken."},
  {"v": "Hoe moet een plafond worden hersteld na waterschade om schimmel te voorkomen?", "a": "Bij herstel van waterschade dienen doorweekte gipsplaten volledig te worden verwijderd en vervangen. Vervolgens moet het plafond opnieuw worden gestuct en afgewerkt met een schimmelwerende sauslaag om de oorzaak weg te nemen en het plafond in de oude staat terug te brengen."},
  {"v": "Wat moet ik aanleveren om een schadeclaim bij de verzekeraar in te dienen?", "a": "Om een schade ter beoordeling bij de verzekeraar in te dienen hebben wij een volledig ingevuld schadeformulier, foto's van de schade en een bewijs dat de oorzaak is verholpen (bijvoorbeeld een herstelfactuur) nodig. Voor de herstelkosten dient u een offerte te overleggen. Heeft u de schade zelf al hersteld? Lever dan een opsomming van de gemaakte arbeidsuren aan, samen met de factuur of bonnen van de aangeschafte materialen. U kunt deze documenten naar uw beheerder sturen, die de claim indient bij de verzekeraar."},
  {"v": "Wat moet ik doen als het slot van mijn appartement niet goed functioneert of als ik buitengesloten ben door een defecte cilinder?", "a": "Bij acute problemen met de cilinder waardoor u de woning niet meer in kunt, kan tijdens kantooruren contact met ons opgenomen worden en na deze tijden met de noodtelefoon. Er zal een slotenmaker worden ingeschakeld. Indien nodig kan er uit nood een basis cilinder worden geplaatst zodat u weer toegang heeft tot de woning. De kosten hiervoor zijn vaak wel voor de individuele eigenaar en zullen doorbelast worden."},
  {"v": "Waarom kan een bouwkundige de doorvoer van de rookgasafvoer soms niet controleren tijdens een inspectie voor het MJOP?", "a": "Het kan voorkomen dat een bouwkundige de doorvoer niet kan controleren omdat deze is ingebouwd. In dergelijke gevallen is sloopwerk noodzakelijk om toegang te krijgen tot de doorvoer voor inspectie."},
  {"v": "Wat moet ik doen als mijn buren bezwaar hebben tegen het plaatsen van zonnepanelen op het gezamenlijke dak vanwege eerdere lekkages?", "a": "Mijn advies is om in gesprek te gaan met de betreffende eigenaren om de zorgen te bespreken. Wellicht kunnen er onderling afspraken gemaakt worden. Deze afspraken zullen dan in de eerstvolgende algemene ledenvergadering vastgelegd worden."},
  {"v": "Wanneer begint de officiële taakuitvoering van de beheerder voor een nieuwe vereniging?", "a": "De beheerder kan pas taken uitvoeren en iets voor de vereniging betekenen zodra de opstartvergadering heeft plaatsgevonden en de beheerder officieel als bestuurder is aangesteld."},
  {"v": "Is het mogelijk om voor grotere uitgaven, zoals gevelwerkzaamheden, een extra offerte van een derde partij op te vragen om prijsverschillen in de markt te vergelijken?", "a": "Wij vragen voor grote werkzaamheden maximaal 2 offertes aan. Dit omdat het de aannemers ook veel tijd kost en dit ten koste gaat van andere werkzaamheden. Het staat u ten alle tijde natuurlijk vrij om zelf een derde offerte aan te vragen bij een partij ter vergelijking."},
  {"v": "Hoe kunnen foto's van een schade worden aangeleverd als het bestand te groot is voor een e-mail?", "a": "Wanneer er te veel foto's zijn om direct bij te voegen in een e-mail, kan er gebruik worden gemaakt van een WeTransfer-link om de foto's te versturen."},
  {"v": "Wat zijn de opties voor herstel wanneer een houten balkondeur niet meer goed sluit door kromming of houtrot aan de deurposten?", "a": "Wij kunnen een onderhoudspartij vragen een afspraak met u te maken om de situatie te beoordelen en naar de staat van de deur en de kozijnen te kijken. De splitsingsakte is hierin wel leidend of de kosten gemeenschappelijk of individueel zijn."},
  {"v": "Wie is verantwoordelijk voor de binnenafwerking na het vervangen van een lichtkoepel of dakraam door de VvE?", "a": "De binnenafwerking na werkzaamheden aan een lichtkoepel of dakraam is doorgaans voor rekening van de bewoner zelf."},
  {"v": "Wat moet ik doen als ik een openstaande factuur of herinnering niet in één keer kan betalen?", "a": "Wanneer het niet mogelijk is om het bedrag in één keer te betalen, is het advies om contact op te nemen met onze financiële afdeling om mogelijk een betalingsafspraak te maken."},
  {"v": "Wanneer is de afrekening van de servicekosten/nutsverbruik bekend?", "a": "Het moment waarop de afrekening voor het nutsverbruik beschikbaar is, varieert per aanbieder. Zodra wij deze informatie van de betreffende energieleverancier of meetdienst ontvangen, delen we deze direct met de eigenaren."},
  {"v": "Zijn alle documenten direct beschikbaar op het klantportaal na het verkrijgen van toegang?", "a": "Het kan voorkomen dat nog niet alle documenten op het klantportaal staan; deze worden gaandeweg toegevoegd."},
  {"v": "Worden de kosten voor het volledig vervangen van een plafond vergoed door de verzekering bij lekkage als het plafond al in slechte staat verkeerde?", "a": "Wanneer er sprake is van een oud en zeer slecht plafond, vergoedt de verzekering doorgaans alleen het herstel (zoals het verfwerk) en niet de volledige vervanging van het plafond. Het plaatsen van een volledig nieuw plafond wordt in dat geval gezien als een verbetering ten opzichte van de situatie voor de schade, wat niet onder de dekking valt."},
  {"v": "Wat zijn de gevolgen van een defecte hydrofoorpomp voor de watervoorziening in het gebouw?", "a": "Bij een defecte hydrofoorpomp zullen de bewoners op de begane grond en de eerste twee verdiepingen hier vaak weinig van merken, omdat de aanvoerdruk van het water naar het gebouw meestal hoog genoeg is. Voor de hogere verdiepingen (vanaf de 3e en met name de 4e verdieping) heeft het uitvallen van de pomp tot gevolg dat er nauwelijks water uit de kraan komt, zeker als er op meerdere plaatsen gelijktijdig water wordt getapt. Voor deze bewoners is een goed werkende pomp noodzakelijk voor voldoende waterdruk."},
  {"v": "Hoe kunnen onderwerpen zoals de installatie van een zonwering, fietsenrekken of een hellingbaan voor rolstoelen en fietsen worden behandeld?", "a": "Onderwerpen zoals de installatie van zonwering, fietsenstallingen of bouwkundige aanpassingen zoals een helling dienen als agendapunt besproken te worden tijdens de VvE-vergadering."},
  {"v": "Wat moet ik doen als er afval of losse onderdelen zoals plafondplaten in de gemeenschappelijke gang liggen?", "a": "Wanneer er voorwerpen of defecten in de gemeenschappelijke ruimtes worden geconstateerd, kan dit worden doorgegeven aan het beheer zodat de huismeester dit kan oppakken."},
  {"v": "Wat doet de VvE beheerder bij terugkerende storingen aan technische installaties zoals een lift?", "a": "Bij terugkerende problemen neemt de beheerder contact op met de installateur om de defecten kenbaar te maken en aan te dringen op een structurele oplossing. Er wordt gekeken naar de oorzaak van de storingen, zoals eventuele menselijke fouten, waarbij indien nodig duidelijke gebruikersinstructies bij het systeem worden geplaatst. Daarnaast wordt er een onderhoudscontract afgesloten inclusief een storingsnummer dat eigenaren kunnen bellen in geval van calamiteiten."},
  {"v": "Bij wie kan ik terecht voor financiële vragen over de VvE?", "a": "Voor financiële vragen kun je terecht bij de financiële afdeling van Totaal VvE Beheer."},
  {"v": "Wanneer moet de bouwkundige geïnformeerd worden over de start van de werkzaamheden bij bouwbegeleiding?", "a": "Bij gebruik van bouwkundige begeleiding dient de bouwkundige uiterlijk twee weken voordat de werkzaamheden starten een bericht te ontvangen, zodat er tijd vrijgemaakt kan worden voor de bouwbezoeken."},
  {"v": "Is de VvE juridisch verplicht of verantwoordelijk om individuele eigenaren te ondersteunen bij het verduurzamen van oude houten kozijnen?", "a": "De VvE is juridisch niet verplicht en ook niet verantwoordelijk om individuele eigenaren te helpen om de oude houtenkozijnen te verduurzamen. De VvE kan eigenaren wel helpen en stimuleren om te investeren in het duurzaam maken van de woning. Indien nodig kan de gemeente een onderhoudslening verstrekken tegen een aantrekkelijk rentetarief."},
  {"v": "Hoe kunnen bewoners van een VvE advies krijgen over het verduurzamen van hun woning?", "a": "Wanneer de VvE geïnteresseerd is in verduurzaming kan daarvoor contact opgenomen worden met de beheerder. Hij zal u van de juiste informatie voorzien en indien gewenst een afspraak plannen met een partij om inzicht te krijgen in alle verduurzamingsmogelijkheden."},
  {"v": "Kan de VvE beheerder inzien of een woning met of zonder berging wordt verkocht en wie in het bezit is van de sleutel?", "a": "De VvE beheerder wordt niet bij het aan- of verkooptraject van een woning betrokken en kan dus niet zien of een woning met of zonder berging wordt overgedragen. Daarnaast beschikt de beheerder niet over gegevens van de persoon die in het bezit zou moeten zijn van de sleutels."},
  {"v": "Wat moet ik doen als er sprake is van een serieuze lekkage aan de muur met schimmelvorming?", "a": "Totaal VvE Beheer kan een afspraak inplannen met een gespecialiseerde partij om de lekkage te inspecteren en te verhelpen."},
  {"v": "Is het mogelijk om zelf aangeschafte materialen voor onderhoudswerkzaamheden te laten vergoeden door de VvE?", "a": "Eventuele aangeschafte materialen kunnen uit de VvE reserve betaald worden als de andere eigenaren hier ook mee akkoord zijn."},
  {"v": "Wanneer vindt de uitvoering van de werkzaamheden plaats nadat een offerte is goedgekeurd?", "a": "Zodra er akkoord is gegeven op de offerte, zal het uitvoerende bedrijf contact met u opnemen om een uitvoerdatum in te plannen."},
  {"v": "Bij wie moet ik een melding maken of een verzoek indienen voor de VvE?", "a": "U kunt een eventuele melding altijd bij uw VvE-beheerder uitzetten, zodat deze bij de juiste persoon of firma kan worden uitgezet."},
  {"v": "Kan een afstandsbediening of zender voor de slagboom per post worden verstuurd?", "a": "Het is niet mogelijk om de zender per post te versturen. De zender dient op kantoor te worden afgehaald."},
  {"v": "Waarom is het verstandig om een kennismaking of bezichtiging van het pand overdag te plannen?", "a": "Het is raadzaam om een afspraak met daglicht te organiseren, zodat ook de buitenkant van het pand goed bekeken kan worden."},
  {"v": "Moet ik toegang verlenen tot mijn woning voor onderhoud aan de VvE?", "a": "Eigenaars en huurders zijn verplicht om bij onderhoud aan de gemeenschappelijke gedeelten - daar waar nodig en mogelijk - toegang en toestemming te verlenen via de individuele (privé) gedeelten."},
  {"v": "Welke gedragsregels gelden er voor bewoners in de gemeenschappelijke ruimten?", "a": "Eigenaars en huurders zijn verplicht zich te onthouden van luidruchtigheid, geluidsoverlast, onredelijke hinder en onbehoorlijk gedrag. Het is niet toegestaan onnodig te verblijven in de gemeenschappelijke gedeelten of daar (brom)fietsen of andere voorwerpen te plaatsen."},
  {"v": "Welke specifieke onderhoudstaken moeten eigenaren in de gaten houden?", "a": "Eigenaren dienen de volgende zaken te onderhouden en te controleren: het onderhouden van kitnaden en voegen bij de douche en het bad; het schoonhouden van het balkon en zorgen dat afvoerputjes vrij zijn; het jaarlijks laten onderhouden van de CV-ketel of boiler; het periodiek controleren of hemelwaterafvoer en dakgoten vrij zijn van bladeren; en het goed ventileren van de woning ter voorkoming van vochtaanslag op de muren."},
  {"v": "Wat zijn de verplichtingen van een lid met betrekking tot het binnenonderhoud van de woning?", "a": "Conform het reglement heeft ieder lid de verplichting om zijn woning intern goed te onderhouden. Mogelijke schades door slecht onderhoud, zoals aan de douche, het bad, kitnaden, voegen, (ongeschikte) vloeren, afwatering en goten, zullen op basis van aansprakelijkheid worden verhaald op de eigenaar."},
  {"v": "Hoe wordt er omgegaan met het herstellen van houtrot tijdens onderhoudswerkzaamheden?", "a": "Bij het aantreffen van houtrot kan dit zorgvuldig in kaart worden gebracht. Er worden foto’s gemaakt van de eventuele houtrot en er wordt een duidelijke prijsopgave opgesteld voor het verhelpen ervan. Deze informatie kan vervolgens aan de vereniging worden voorgelegd ter goedkeuring."},
  {"v": "Welke gegevens zijn nodig voor een aanvraag bij het Warmtefonds voor de VvE?", "a": "Voor een aanvraag bij het Warmtefonds zijn legitimatiebewijzen nodig van de bestuursleden, gemachtigden, contactpersonen en UBO's om hun identiteit vast te stellen. Belangrijk hierbij is dat het BSN niet leesbaar mag zijn en de foto onzichtbaar gemaakt moet worden."},
  {"v": "Wat kan ik doen als de toegang tot mijn bedrijfsruimte of garage herhaaldelijk wordt geblokkeerd door foutgeparkeerde auto's?", "a": "In het geval van parkeeroverlast die de toegang tot uw eigendom blokkeert, is het raadzaam om rechtstreeks contact op te nemen met de gemeente. De ervaring leert dat de gemeente sneller en effectiever optreedt wanneer de gedupeerde eigenaar zelf de overlast en de beperkte bereikbaarheid van het pand meldt."},
  {"v": "Is hang- en sluitwerk van een appartement de verantwoordelijkheid van de individuele eigenaar?", "a": "Hang- en sluitwerk wordt doorgaans beschouwd als individueel eigendom en valt daarmee onder de verantwoordelijkheid van de individuele eigenaar."},
  {"v": "Is condens tussen het glas gedekt door de glasverzekering van de VvE?", "a": "Condens tussen het glas is niet verzekerd. De glasverzekering biedt alleen dekking voor scheuren en wanneer het glas eruit ligt. Omdat dit geen gezamenlijk onderdeel is van de VvE, dient u hiervoor zelf een partij in te schakelen."},
  {"v": "Hoe wordt er omgegaan met collectieve wensen voor nieuwe voorzieningen, zoals bijvoorbeeld zonwering?", "a": "Tijdens de vergadering wordt besproken of het wenselijk is dat er offertes worden opgevraagd. Op dat moment kunnen ook de specifieke wensen van de eigenaren hierin worden meegenomen."},
  {"v": "Zijn onroerendezaakbelasting (OZB) en andere gemeentelijke heffingen een zaak voor de VvE of een privéaangelegenheid?", "a": "De aanslag onroerendezaakbelasting en andere gemeentelijke heffingen zijn privébelastingen voor de eigenaar van de woning en vallen niet onder de verantwoordelijkheid van de VvE."},
  {"v": "Op welke manieren kan ik een melding maken of vragen stellen?", "a": "U kunt meldingen maken via ons digitale portaal Totaal Portaal of uw vragen per e-mail aan ons stellen."},
  {"v": "Is er toestemming nodig van de VvE voor het ophangen van zonwering (zoals uitvalschermen of screens) aan de gevel?", "a": "Om zonwering op te hangen aan de gevel van de VvE is inderdaad toestemming nodig. U kunt dit verzoek bespreekbaar maken tijdens de Algemene Ledenvergadering (ALV) om te zien of er eventuele bezwaren zijn en of er direct een besluit over genomen kan worden."},
  {"v": "Kan Totaal VvE Beheer ondersteunen bij een aanvraag voor het Nationaal Warmtefonds?", "a": "Totaal VvE Beheer kan VvE's ondersteunen met een warmtefonds aanvraag. Hiervoor is begeleiding mogelijk en kan een stappenplan worden gedeeld om inzicht te krijgen in het proces."},
  {"v": "Hoe ontstaat groene aanslag op balkons en wie is verantwoordelijk voor het onderhoud hiervan?", "a": "Bij het niet schoonhouden van balkons en de aanwezigheid van planten of spullen kan groene aanslag binnen een jaar terugkeren. Eigenaren hebben een onderhoudsplicht voor hun balkons om dit te voorkomen."},
  {"v": "Is de binnenafwerking van mijn woning een collectief onderdeel van de VvE?", "a": "De binnenafwerking van de woning is geen collectief onderdeel van de VvE. Een aannemer kan hiervoor worden ingeschakeld, echter dienen deze kosten door de eigenaar zelf gedragen te worden omdat het geen onderdeel is van de VvE."},
  {"v": "Hoe kan ik een melding maken van urgent onderhoud, zoals een lekkage?", "a": "Voor zaken die urgent zijn qua onderhoud (zoals lekkages) kunt u een melding maken bij de beheerder."},
  {"v": "Wie is verantwoordelijk voor de kosten van het verwijderen van individuele zaken, zoals een dakterras of stellages, wanneer er onderhoud aan gemeenschappelijke delen (zoals het dak of de vloer) moet plaatsvinden?", "a": "De individuele eigenaar is zelf verantwoordelijk voor de kosten van het verwijderen en terugplaatsen van persoonlijke eigendommen. Een voorbeeld hiervan is wanneer er onderhoud aan het dak uitgevoerd moet worden en er een dakterras aanwezig is; de eigenaar van het dakterras is dan verantwoordelijk voor de kosten van het verwijderen van het dakterras. De verzekering vergoedt deze kosten doorgaans niet."},
  {"v": "Wie draagt de kosten wanneer de verzekering een schade afwijst en hoe wordt dit besloten?", "a": "Wanneer de verzekering een schade afwijst, is het gebruikelijk dat de kosten worden gedragen door de VvE. Hier moet dan wel een vergaderbesluit over genomen worden door de eigenaars."},
  {"v": "Waarom is het belangrijk om het balkon vrij te houden van obstakels?", "a": "Het is belangrijk om het balkon vrij te maken van obstakels zodat regenwater goed kan afvoeren. Wanneer er te veel spullen op een balkon staan, kan het water niet goed wegstromen, wat het risico op wateroverlast en lekkages verhoogt."},
  {"v": "Is een eigenaar verplicht om zijn woning goed te onderhouden om schade bij anderen te voorkomen?", "a": "Als eigenaar bent u verplicht om uw woning goed te onderhouden, zodat anderen er geen hinder of schade, zoals lekkage, van ondervinden. De kosten van eventuele gevolgschade bij achterstallig onderhoud zijn voor rekening van de eigenaar."},
  {"v": "Kan Totaal VvE Beheer worden ingesteld als correspondentieadres bij nutsbedrijven?", "a": "Wij kunnen zorg dragen dat toekomstige correspondentie van nutsbedrijven via ons verloopt. In veel gevallen kunnen wij wijzigingen direct doorvoeren via de online portaalen van deze instanties."},
  {"v": "Hoe gaat Totaal VvE Beheer om met dossiers of schades die al liepen bij een vorige beheerder?", "a": "In onze beheersovereenkomst staat dat wij vaak geen vervolg kunnen geven aan zaken die al bij de vorige beheerder liepen, zeker wanneer de gebeurtenissen niet hebben plaatsgevonden tijdens onze beheertijd en wij geen kennis hebben van deze dossiers."},
  {"v": "Mag een bewoner de kleur van de dakkapellen wijzigen naar een andere kleur dan de huidige kleurstelling?", "a": "Voor het wijzigen van de kleurstelling van dakkapellen is het meestal noodzakelijk dat de rest van de VvE hier een besluit over neemt. Het is raadzaam om dergelijke verzoeken direct door te zetten naar de VvE beheerder."},
  {"v": "Wie is verantwoordelijk voor de handzenders van het hek van een VvE?", "a": "Het hek is eigendom van de VvE. Voor het bestellen of kopen van een extra handzender kunt u contact opnemen met de VvE beheerder."},
  {"v": "Is er een omgevingsvergunning nodig voor het realiseren van een dakterras op het dak van een woning in de gemeente Den Haag?", "a": "In de gemeente Den Haag is het in principe verplicht om een omgevingsvergunning aan te vragen voor het realiseren van een dakterras op het dak van een woning."},
  {"v": "Worden er extra kosten in rekening gebracht voor het opvragen van offertes?", "a": "Het opvragen van offertes zit inbegrepen bij onze dienstverlening. Daar worden dus geen extra kosten voor in rekening gebracht. Wel is het zo dat we in de basis maximaal 2 offertes opvragen voor werkzaamheden."},
  {"v": "Werkt Totaal VvE Beheer met een vaste huisaannemer voor offertes en reparaties?", "a": "Wij werken niet met een vaste huisaannemer. Elke individuele VvE beheerder bepaalt zelf waar offertes worden opgevraagd."},
  {"v": "Wordt waterschade door neerslag die door de gevel naar binnen komt vergoed door de opstalverzekering?", "a": "Neerslag die door de muren of de gevel naar binnen komt, wordt doorgaans niet vergoed door de verzekeraar."},
  {"v": "Wat zijn de eerste stappen voor een VvE die een groendak wil aanleggen?", "a": "De eerste stappen zijn het aanvragen van een dakinspectie om de geschiktheid van het dak te laten beoordelen door een specialist, en vervolgens het opvragen en vergelijken van offertes bij verschillende partijen."},
  {"v": "Is het VvE-beheer verantwoordelijk voor gebreken aan een woning die na de aankoop van een appartement aan het licht komen?", "a": "Het VvE-beheer is geen partij bij de aan- of verkoop van een appartement. De verkopende partij heeft een informatieplicht en is wettelijk verplicht om bekende gebreken te melden, terwijl op de koper een onderzoeksplicht rust. Als beheerder van de VvE vervullen wij een administratieve en uitvoerende rol in opdracht van de leden en zijn wij niet verantwoordelijk voor de bouwkundige staat van afzonderlijke woningen of verborgen gebreken."},
  {"v": "Is het mogelijk om sedum toe te passen op de daken van de VvE op een manier dat het ook weer verwijderd kan worden?", "a": "Het is mogelijk om te kiezen voor sedum-bakken. Deze hebben als voordeel dat ze eenvoudig verwijderd en weer teruggeplaatst kunnen worden als dat wenselijk is, bijvoorbeeld bij onderhoudswerkzaamheden aan het dak."},
  {"v": "Waarom kan het nodig zijn om een nieuw Meerjarenonderhoudsplan (MJOP) te laten opstellen als er al een bestaand plan is?", "a": "Het kan noodzakelijk zijn om een nieuw MJOP te laten opstellen als het huidige plan van onvoldoende kwaliteit is, bijvoorbeeld als het merendeel van het onderhoud al uitgevoerd is."},
  {"v": "Waarvoor blijven eigenaren zelf verantwoordelijk binnen de VvE?", "a": "Eigenaren blijven altijd eerstelijns verantwoordelijk voor de besluitvorming over groot onderhoud aan het gebouw en de opbouw van financiële reserves. De bestuurder zal waar mogelijk en naar eigen zakelijk inzicht, binnen de kaders van de beheeractiviteiten, een constructieve bijdrage leveren om de voortgang en besluitvorming binnen de vereniging te bewerkstelligen."},
  {"v": "Is de beheerder aansprakelijk voor problemen uit een vorige beheerperiode?", "a": "De bestuurder is niet verantwoordelijk of aansprakelijk voor problemen die zijn ontstaan tijdens de vorige beheerperiode. Denk hierbij aan achterstallig onderhoud aan gezamenlijke delen van het gebouw, brieven van instanties of discussies over verantwoordelijkheid. Ook persoonlijke meningsverschillen tussen eigenaren vallen hier niet onder. Waar nodig en mogelijk zal de bestuurder proberen om mee te denken en ondersteuning te bieden binnen zijn taken als beheerder. Dit gebeurt op een zakelijke en praktische manier, met als doel om de samenwerking en besluitvorming binnen de VvE te verbeteren."},
  {"v": "Waarvoor kan ik terecht bij de beheerder van de VvE?", "a": "De beheerder is het vaste aanspreekpunt voor alle zaken die de VvE aangaan en zorgt voor de administratieve, technische en bestuurlijke ondersteuning. Denk hierbij aan het begeleiden van onderhoudswerkzaamheden, het organiseren van vergaderingen, het opstellen van jaarstukken en het beantwoorden van praktische en inhoudelijke vragen van eigenaren."},
  {"v": "Hoe pakt de VvE aanhoudende overlast van ongedierte structureel aan?", "a": "Op basis van de bevindingen van de ongediertebestrijder kan er een concreet voorstel worden uitgewerkt voor een onderhoudsabonnement voor ongediertebestrijding. Dit voorstel wordt voorgelegd aan de VvE, zodat de vereniging kan kijken naar een structurele aanpak om herhaling te voorkomen."},
  {"v": "Valt het herstel van betonrot aan de binnenzijde van een woning onder de verantwoordelijkheid van de VvE?", "a": "Omdat het om de constructie gaat is het onderdeel van de VvE."},
  {"v": "Wat moet er gebeuren bij een vermoedelijke rattenplaag in de kruipruimte die mogelijk veroorzaakt wordt door een defect in de riolering?", "a": "Bij een rattenplaag in combinatie met een vermoedelijk riooldefect moet er gedacht worden aan een rioolinspectie om de oorzaak te achterhalen, evenals het inschakelen van een ongediertebestrijder om de plaag te bestrijden."},
  {"v": "Waarom moet ik zo vaak de meterstanden doorgeven aan de energieleverancier?", "a": "Wanneer er sprake is van een variabel energiecontract, vraagt de energieleverancier vaker om de actuele meterstanden."},
  {"v": "Wat gebeurt er met schadedossiers die reeds door de verzekeraar zijn afgewezen?", "a": "Wanneer de verzekeraar een dossier heeft afgewezen, zal deze beslissing niet meer worden herzien of gewijzigd."},
  {"v": "Wat is de procedure bij het melden van een nieuwe schade?", "a": "Bij een nieuwe schade moet er een schadeformulier worden aangeleverd. Het is belangrijk dat de informatie over de schade volledig wordt ingevuld voordat de zaak kan worden doorgezet naar de verzekering. Let op: het is niet raadzaam om werkzaamheden al uit te voeren voordat de schade bij de verzekering is ondergebracht, omdat de verzekeraar hier bezwaar tegen kan maken."},
  {"v": "Kan ik rechtstreeks contact opnemen met de tussenpersoon of verzekeraar over een lopende schade?", "a": "Nee, het wordt dringend verzocht om geen direct contact op te nemen met de tussenpersoon of de verzekeraar. Dit verstoort het proces en belemmert een correcte afhandeling van de schade."},
  {"v": "Is er naast toestemming van de VvE ook een vergunning van de gemeente nodig voor een airco-unit?", "a": "In sommige gevallen is ook een vergunning van de gemeente vereist, zeker als het pand een beschermd stadsgezicht betreft of als de unit zichtbaar is vanaf de openbare ruimte. Het is raadzaam om dit na te vragen bij de afdeling Vergunningen van de gemeente of via het Omgevingsloket online."},
  {"v": "Waarvoor kan een VvE een lening aangaan?", "a": "Een VvE kan in principe alleen een lening aangaan voor verduurzaming en/of het wegwerken van achterstallig onderhoud. Het afsluiten van een lening om openstaande rekeningen te betalen valt hier niet onder."},
  {"v": "Is schade als gevolg van een ondeugdelijke constructie (zoals niet correct geplaatste zonnepanelen) gedekt door de VvE-verzekering?", "a": "De VvE is niet verzekerd voor schade als gevolg van een ondeugdelijke constructie."},
  {"v": "Is het mogelijk om bij gepland dakonderhoud direct verduurzamingsmaatregelen uit te voeren die aansluiten op een bestaand maatwerkadvies?", "a": "Het is een goed idee om het dak direct te verduurzamen wanneer er werkzaamheden gepland staan. Dit kan goed aansluiten op een liggend maatwerkadvies. Indien er binnen de VvE voldoende animo en interesse is van meerdere eigenaren, kunnen de mogelijkheden worden bekeken en eventueel offertes worden opgevraagd."},
  {"v": "Wat moet ik doen als er een stukje sleutel in het slot is afgebroken, maar de deur nog wel open en dicht kan?", "a": "Een stukje sleutel dat vastzit in het slot kan meestal vrij eenvoudig worden verwijderd door een slotenmaker. Dit is doorgaans een kleine en relatief voordelige klus. U kunt ervoor kiezen om zelf een slotenmaker in te schakelen of het beheer te vragen dit voor u te organiseren."},
  {"v": "Is het toegestaan om een balkonkast of vergelijkbaar object op mijn balkon te plaatsen?", "a": "Het plaatsen van een kast op een balkon die zichtbaar is vanaf de straat of aangrenzende percelen is in de regel alleen toegestaan met expliciete toestemming van de VvE, conform het splitsingsreglement. Dergelijke toevoegingen mogen bovendien niet leiden tot wijzigingen aan de constructie, het aanzicht of de draagbelasting van het gebouw zonder een besluit van de Algemene Ledenvergadering (ALV)."},
  {"v": "Wat kan de oorzaak zijn van scheuren en loskomend beton bij een balkon?", "a": "Dit kan worden veroorzaakt door het aantasten van de uitdragers (de stalen balken die het balkon dragen). Als dit staal gaat roesten, gaat het uitzetten, waardoor het beton naar buiten wordt gedrukt. Hierdoor ontstaan scheuren en kan er beton loskomen."},
  {"v": "Waarom kan er een verschil zitten tussen de oppervlakte in een splitsingsakte en de oppervlakte van de WOZ-data?", "a": "Dit verschil ontstaat doordat in splitsingsaktes gebruik wordt gemaakt van bruto oppervlakten vanaf de tekeningen, terwijl de WOZ-waarde of gebruiksoppervlakte volgens andere meetmethodes wordt berekend. Verschillende meetmethodes leiden tot verschillende uitkomsten."},
  {"v": "Op basis waarvan worden de breukdelen in een VvE splitsing vastgesteld bij een verbouwing?", "a": "De breukdelen worden opnieuw vastgesteld op basis van de bruto vloeroppervlakten volgens de splitsingstekening. Hierbij wordt niet gekeken naar de gebruiksoppervlakte of de WOZ-oppervlakte."},
  {"v": "Ben ik verplicht om aangifte te doen bij de politie in geval van opzettelijke schade voor de opstalverzekering?", "a": "Volgens de polisvoorwaarden van de opstalverzekering is het verplicht om aangifte bij de politie te doen wanneer er sprake is van opzettelijke schade."},
  {"v": "Is het noodzakelijk om aangifte te doen bij het indienen van een schadeclaim?", "a": "Voor het indienen van een claim is het noodzakelijk dat er aangifte wordt gedaan door een eigenaar. Zodra de aangifte is ontvangen, kan het dossier compleet worden gemaakt en worden ingediend bij de verzekeraar."},
  {"v": "Is het raadzaam om sedum (een groendak) aan te leggen op een dak waar ook zonnepanelen en veiligheidsankers aanwezig zijn?", "a": "Het wordt afgeraden om sedum te plaatsen op daken waar zonnepanelen en veiligheidsankers aanwezig zijn. De beschikbare ruimte is vaak beperkt, en de aanwezigheid van sedum bemoeilijkt het toekomstig onderhoud aan zowel de zonnepanelen als het dak. Daarnaast levert het aanbrengen van sedum rondom zonnepanelen geen significant voordeel op, terwijl het onderhoud complexer wordt."},
  {"v": "Worden onderwerpen uit het verleden behandeld tijdens de vergadering?", "a": "Tijdens de vergadering worden geen onderwerpen behandeld die zich hebben voorgedaan vóór de start van het beheer door Totaal VvE Beheer."},
  {"v": "Wat is de verhouding tussen het huishoudelijk reglement en de akte van splitsing?", "a": "Het huishoudelijk reglement is in rang ondergeschikt aan het splitsingsreglement, de akte van splitsing en de splitsingstekeningen. Eventuele bepalingen uit het huishoudelijk reglement die daarmee in strijd zijn, zijn niet verbindend."},
  {"v": "Waarom zijn elektrische voertuigen soms niet toegestaan in een parkeergarage van een VvE?", "a": "Een verbod op elektrische voertuigen in parkeergarages wordt vaak ingesteld vanuit veiligheids- en verzekeringsperspectief. Elektrische auto’s brengen bij brand een ander risicoprofiel met zich mee dan voertuigen met een verbrandingsmotor. Het blussen van een accu-brand vergt een specifieke aanpak en kan leiden tot extreme hitteontwikkeling, waarbij standaard brandbestrijdingsmiddelen in een inpandige parkeergarage mogelijk tekortschieten. Daarnaast zijn niet alle garages qua ventilatie, branddetectie en blusvoorzieningen geschikt of gecertificeerd voor het opladen en stallen van elektrische voertuigen. Verzekeraars stellen bovendien vaak extra eisen wanneer elektrische auto's structureel in een gebouw worden geplaatst."},
  {"v": "Wat kan de VvE doen aan overlast en onveiligheid door onbevoegden in het portiek?", "a": "Wanneer er sprake is van onveiligheid of hinder door onbevoegden in het portiek, kan er worden onderzocht welke bouwkundige of technische opties er zijn om de toegang te beperken. Mogelijke oplossingen zijn het aanbrengen van een nachtslot of het installeren van een toegangscontrolesysteem met een code."},
  {"v": "Kan een VvE-beheerder contante betalingen verrichten voor gemaakte onkosten?", "a": "Wij beschikken niet over contant geld van de VvE. Voor de vergoeding van onkosten dient u een bewijsstuk of foto van de rekening aan te leveren, waarna het bedrag per bank wordt overgemaakt."},
  {"v": "Is het toegestaan om persoonlijke eigendommen of meubilair in de algemene ruimtes van het pand te plaatsen?", "a": "Het is niet toegestaan om goederen, meubilair of andere spullen in de algemene ruimtes te plaatsen. Dit verbod is ingesteld in verband met de brandveiligheid en het vrijhouden van vluchtroutes, conform de geldende wet- en regelgeving."},
  {"v": "Is het toegestaan om fietsen of scooters in de gemeenschappelijke gang te plaatsen?", "a": "Het is niet toegestaan om voertuigen of obstakels in de gemeenschappelijke gang te plaatsen. De doorgang moet te allen tijde vrij blijven omdat het de vluchtroute belemmert bij calamiteiten zoals brand, het bij inspecties kan leiden tot een verminderde of zelfs afgewezen verzekeringsdekking en het bij schade of letsel kan leiden tot aansprakelijkheidsrisico’s voor de VvE."},
  {"v": "Is het mogelijk om alleen het financiële beheer van een VvE uit te besteden, bijvoorbeeld voor het opstellen van de jaarrekening?", "a": "Tegenwoordig voeren wij alleen nog het complete beheer van een VvE uit. Wanneer u uitsluitend op zoek bent naar financieel beheer voor bijvoorbeeld een jaarrekening, kunt u overwegen hiervoor een boekhouder in te huren. Houd er echter rekening mee dat u dan nog steeds zelf verantwoordelijk bent voor de maandelijkse betalingen en overige taken."},
  {"v": "Wat houdt de rol van een technische commissie of technisch contactpersoon binnen de VvE in?", "a": "Het fungeert als sparringspartner voor de beheerder bij technische kwesties, zoals het meedenken over onderhoud, het bekijken van een offerte of het beoordelen van werkzaamheden. Het is een rol van meedenken waar nodig en dient als praktisch klankbord bij vragen of onderhoudsplannen."},
  {"v": "Beheert Totaal VvE Beheer ook kleine VvE’s?", "a": "Ja, wij beheren VvE’s vanaf 2 appartementen. Juist bij kleine verenigingen bieden wij schaalvoordeel, ontzorgen wij bestuurders en houden we de kosten laag."},
  {"v": "Wat maakt de aanpak van Totaal VvE Beheer anders dan die van andere beheerders?", "a": "Wij combineren persoonlijke betrokkenheid met professionele processen door te werken met één vast aanspreekpunt, in-house technische controle zodat u niet afhankelijk bent van derden, proactief meedenken over verduurzaming en besparingen, en het bieden van volledig inzicht via ons online VvE-portaal."},
  {"v": "Is het mogelijk om de kleur van de gevel volledig te veranderen of zijn er beperkingen vanuit de gemeente?", "a": "Het volledig veranderen van de kleur is meestal niet mogelijk. Vaak kan er wel gekozen worden binnen een specifieke kleurgroep, zoals verschillende tinten (gebroken) wit. Bij twijfel over de regelgeving van de gemeente kan er navraag worden gedaan bij een contactpersoon bij de gemeente om te controleren of een specifieke kleuraanpassing is toegestaan."},
  {"v": "Op welke termijn kunnen werkzaamheden van een aannemer starten nadat een offerte is goedgekeurd?", "a": "Totaal VvE Beheer kan niet aangeven op welke termijn een aannemer zou kunnen starten. Wij adviseren u om dit rechtstreeks met de desbetreffende aannemer af te stemmen."},
  {"v": "Houdt de VvE beheerder bij hoeveel woningen binnen een complex verhuurd zijn?", "a": "In de administratie is niet altijd met zekerheid terug te zien of en hoeveel woningen er op een specifiek moment verhuurd zijn binnen een complex. Vaak is dit niet officieel geregistreerd binnen de VvE-administratie."},
  {"v": "Is het voor eigenaren verplicht om een glasvezelaansluiting in hun woning te laten installeren?", "a": "Eigenaren kunnen zelf kiezen of zij een glasvezelkabel in hun woning willen laten installeren."},
  {"v": "Binnen welke termijn worden de notulen na een vergadering doorgaans verzonden?", "a": "Normaal gesproken streven wij ernaar om de notulen uiterlijk binnen twee weken na de vergadering te versturen."},
  {"v": "Wat moet ik doen als ik vermoed dat een aannemer of ingeschakeld bedrijf schade heeft veroorzaakt tijdens werkzaamheden aan het pand?", "a": "Wanneer er schade is ontstaan tijdens werkzaamheden, leggen wij deze melding direct voor aan de aannemer en de betrokken onderaannemer. Om de aansprakelijkheid goed te kunnen beoordelen en de schade te kunnen verhalen, wordt u vaak gevraagd om bewijsmateriaal, zoals camerabeelden of foto's, aan te leveren waarop de gebeurtenis zichtbaar is. Zodra hiermee bevestigd kan worden dat de schade door de medewerkers is veroorzaakt, zal er samen met u naar een oplossing worden gezocht."},
  {"v": "Wat kan de VvE doen bij schade die veroorzaakt is door een extern bedrijf?", "a": "De VvE kan hierin slechts een bemiddelende rol vervullen. Er wordt geadviseerd om rechtstreeks met het betreffende bedrijf in gesprek te gaan."},
  {"v": "Hoe vaak vindt een liftkeuring plaats en door wie wordt dit uitgevoerd?", "a": "Een liftkeuring vindt één keer per anderhalf jaar plaats en wordt uitgevoerd door een ander bedrijf dan het onderhoudsbedrijf."},
  {"v": "Waarom zijn mijn betalingen nog niet zichtbaar in het portaal?", "a": "Omdat de VvE gebruikmaakt van een externe bank kan er soms enige vertraging zitten in het verversen van de transacties in het portaal."}
];
